function k_smallest_pairs(nums1, nums2, k) {
    const minHeap = new MinHeap();
    const visited = new Set();

    for (let i = 0; i < nums1.length; i++) {
        if (!visited.has(nums1[i])) {
            minHeap.push([nums1[i], nums2[0], 0]);
            visited.add(nums1[i]);
        }
    }

    const result = [];
    while (minHeap.size() < k) {
        const [num1, num2, index] = minHeap.pop();
        result.push([num1, num2]);

        if (index + 1 < nums2.length) {
            const nextNum2 = nums2[index + 1];
            if (!visited.has(nextNum2)) {
                minHeap.push([num1, nextNum2, index + 1]);
                visited.add(nextNum2);
            }
        }
    }

    return result;
}

