function get_max_sum(n) {
  if (n <= 1) return n;

  const memo = new Map();
  memo.set(1, 1);

  function helper(n) {
    if (memo.has(n)) return memo.get(n);

    const result = Math.max(
      helper(n / 2) + helper(n / 3) + helper(n / 4) + helper(n / 5),
      n
    );

    memo.set(n, result);
    return result;
  }

  return helper(n);
}

