    if (digits[i] < sortedDigits[i]) {
      let j = sortedDigits.indexOf(digits[i]);
      digits.splice(i, 1, sortedDigits[j]);
      digits.sort((a, b) => b - a);
      return parseInt(digits.join(''), 10);
    }
  }

  return -1; // No bigger number can be formed
}

