  let len = str.length;

  // Function to check if a number is a palindrome
  function is_palindrome(num) {
    let str = num.toString();
    let reversed = str.split('').reverse().join('');
    return str === reversed;
  }

  // Iterate from the next number to find the next palindrome
  for (let i = num + 1; i < Math.pow(10, len); i++) {
    if (is_palindrome(i)) {
