function min_Jumps(steps, d) {
    // Initialize the current position and the number of jumps
    let position = 0;
    let jumps = 0;

    // Loop until the current position is greater than or equal to the destination
    while (position < d) {
        // Calculate the maximum distance that can be reached in the current number of steps
        let maxReach = position + steps;

        // If the maximum reach is greater than or equal to the destination, return the number of jumps
        if (maxReach >= d) {
            return jumps + 1;
        }

        // Update the position to the maximum reach
        position = maxReach;

        // Increment the number of jumps
        jumps++;
    }

    // If the loop completes without reaching the destination, return -1 (impossible to reach)
    return -1;
}

