function maxAverageOfPath(cost){
  const N = cost.length;
  const dp = new Array(N).fill().map(() => new Array(N).fill(0));

  // Initialize the first row and first column
  for (let i = 0; i < N; i++) {
    dp[0][i] = cost[0][i];
    dp[i][0] = cost[i][0];
  }

  // Fill the DP table
  for (let i = 1; i < N; i++) {
    for (let j = 1; j < N; j++) {
      dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]) + cost[i][j];
    }
  }

  // Calculate the maximum average
  const maxAverage = dp[N-1][N-1] / (N*N);

  return maxAverage;
}

function maxAverageOfPath(cost){
  const N = cost.length;
  const dp = Array.from({ length: N }, () => Array.from({ length: N }, () => -Infinity));

  function dfs(i, j) {
    if (i === N - 1 && j === N - 1) {
      return cost[i][j];
    }

    if (dp[i][j] !== -Infinity) {
      return dp[i][j];
    }

    let maxCost = -Infinity;
    if (j < N - 1) {
      maxCost = Math.max(maxCost, dfs(i, j + 1));
    }
    if (i < N - 1) {
      maxCost = Math.max(maxCost, dfs(i + 1, j));
    }

    dp[i][j] = cost[i][j] + maxCost;
    return dp[i][j];
  }

  return dfs(0, 0) / (N * N);
}

