function get_total_number_of_sequences(m, n) {
  if (m < 2 || n < 1) return 0; // Early return if m or n is invalid

  // Initialize the dp array with zeros
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1; // There's one way to have an empty sequence

  // Fill the dp array
  for (let i = 1; i <= n; i++) {
    for (let j = 2; j <= m; j++) {
      if (j >= 2 * (i - 1)) {
        dp[i] += dp[i - 1];
      }
    }
  }

  return dp[n];
}

