    // Find the next smallest palindrome by incrementing the last digit
    let lastDigit = str[len - 1];
    let nextLastDigit = parseInt(lastDigit) + 1;

    // If the next last digit is greater than 9, it means we need to increment the previous digit
    if (nextLastDigit > 9) {
      let newNum = parseInt(str.substring(0, len - 1) + nextLastDigit.toString());
      return newNum;
    } else {
      // If the next last digit is 9, we need to adjust the previous digits
      let newNum = parseInt(str.substring(0, len - 1) + '0');
      return newNum;
    }
  } else {
    // If the number is not a palindrome, find the next palindrome by appending the smallest digit
    let newNum = parseInt(str + '0');
    return newNum;
  }
}

