  if (n === 0) return [0];
  if (n === 1) return [0, 1];
  if (n === 2) return [0, 1, 2];

  let sequence = [0, 1, 2];
  for (let i = 3; i <= n; i++) {
    let nextValue;
    if (i % 2 === 0) {
      nextValue = 1 + i / 2;
    } else {
      nextValue = sequence[i - 1] + sequence[i - 2] + sequence[i + 1];
