function rearrange_bigger(n){
  let digits = n.toString().split('');
  let len = digits.length;
  let found = false;

  for(let i = len - 2; i >= 0; i--){
    if(digits[i] < digits[i + 1]){
      let j = len - 1;
      while(digits[j] <= digits[i]){
        j--;
      }
      digits[i] = digits[i] + digits[j];
      digits[j] = digits[i] - digits[j];
      digits.splice(i + 1, len - (i + 1), ...digits.slice(i + 1).sort((a, b) => a - b));
      found = true;
      break;
    }
  }

  if(!found){
    return -1;
  }

  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  const digits = n.toString().split('').map(Number);

  // Start from the second last digit and move towards the first digit
  for (let i = digits.length - 2; i >= 0; i--) {
    // If the current digit is smaller than the digit immediately after it
    if (digits[i] < digits[i + 1]) {
      // Find the smallest digit to the right of the current digit that is greater than it
      let j = i + 1;
      while (j < digits.length && digits[j] <= digits[i]) {
        j++;
      }

      // Swap the found digits
      [digits[i], digits[j - 1]] = [digits[j - 1], digits[i]];

      // Sort the digits to the right of the current position in descending order
      digits.splice(i + 1, digits.length - i - 1).sort((a, b) => b - a);

      // Convert the array of digits back to a number
      return parseInt(digits.join(''));
    }
  }

  // If no bigger number can be formed, return -1
  return -1;
}

