  if (m <= 0 || n <= 0) {
    return 0;
  }

  const dp = Array(n + 1).fill(0);
  dp[1] = 1; // There is only one way to have a sequence of length 1

  for (let i = 2; i <= n; i++) {
    for (let j = i; j <= m; j++) {
      dp[i] += dp[j - 2]; // Add the number of sequences that can be formed with the previous element
    }
  }

