  if (n === 1) return 1; // Base case: If n is 1, there's only one sequence (the number itself).

  let total = 0;

  for (let i = 2; i <= m; i++) {
    total += get_total_number_of_sequences(m, n - 1); // Recursive case: For each possible value of i, add the number of sequences of length n-1 that can be formed with i as the new element.
  }

  return total;
}

