function eulerian_num(n, m) {
    if (n < m || m < 0) {
        return 0; // Eulerian number is not defined for n < m or m < 0
    }

    // Base cases
    if (n === 0 && m === 0) {
        return 1;
    }
    if (n === 1 && m === 0) {
        return 1;
    }
    if (n === 0 && m === 1) {
        return 0;
    }

    // Recursive case
    return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m);
}

