    // Sort both arrays
    nums1.sort((a, b) => a - b);
    nums2.sort((a, b) => a - b);

    let i = 0;
    let j = 0;
    let result = [];

    // Use a two-pointer approach to find the k smallest pairs
    while (i < nums1.length && j < nums2.length && result.length < k) {
        result.push([nums1[i], nums2[j]]);
        // Move the pointer in the array with the smaller element
