function is_undulating(n) {
    if (n < 10) return false; // Single digit numbers are not undulating

    let is increasing = true;
    let is decreasing = false;

    while (n > 9) {
        let lastDigit = n % 10;
        let nextDigit = Math.floor(n / 10) % 10;

        if (lastDigit > nextDigit) {
            if (isDecreasing) return false;
            isIncreasing = false;
        } else if (lastDigit < nextDigit) {
            if (isIncreasing) return false;
            isDecreasing = true;
        }

        n = Math.floor(n / 10);
    }

    return true;
}

