function tri(n){
  if (n === 0) return [];
  if (n === 1) return [3];
  if (n === 2) return [3, 2];

  let sequence = [3, 2, 8];
  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      sequence.push(1 + i / 2);
    } else {
      sequence.push(sequence[i - 1] + sequence[i - 2] + sequence[i + 1]);
    }
  }
  return sequence;
}

function tri(n) {
  if (n < 1) return [];

  let sequence = [3, 1, 2];

  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      sequence.push(sequence[i - 1] + sequence[i - 2]);
    } else {
      sequence.push(sequence[i - 1] + sequence[i - 2] + sequence[i + 1]);
    }
  }

  return sequence.slice(0, n + 1);
}

