function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  let a = 0, b = 1, c = 0, i = 2;
  while (i <= n) {
    c = a + b;
    a = b;
    b = c;
    i++;
  }
  return b;
}

function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = new Map();
  memo.set(0, 0);
  memo.set(1, 1);

  for (let i = 2; i <= n; i++) {
    const a = memo.get(i - 1);
    const b = memo.get(i - 2);
    memo.set(i, a + b);
  }

  return memo.get(n);
}

