function amicable_numbers_sum(limit){
  let sum = 0;
  for (let i = 1; i <= limit; i++) {
    let divisors = divisorsSum(i);
    if (divisors > i && divisorsSum(divisors) === i) {
      sum += i;
    }
  }
  return sum;
}

function divisorsSum(n) {
  let sum = 1;
  for (let i = 2; i <= Math.sqrt(n); i++) {
    if (n % i === 0) {
      sum += i;
      if (i !== n / i) {
        sum += n / i;
      }
    }
  }
  return sum;
}

function amicable_numbers_sum(limit) {
    function isAmicable(num) {
        let sum = 1;
        for (let i = 2; i <= Math.sqrt(num); i++) {
            if (num % i === 0) {
                sum += i + num / i;
            }
        }
        return sum === num && num !== 1;
    }

    let sum = 0;
    for (let i = 2; i <= limit; i++) {
        if (isAmicable(i)) {
            sum += i;
        }
    }
    return sum;
}

function search(arr){
  let left = 0;
  let right = arr.length - 1;

  while (left < right) {
    let mid = Math.floor((left + right) / 2);

    if (arr[mid] === arr[mid + 1]) {
      left = mid + 2;
    } else {
      right = mid;
    }
  }

  return arr[left];
}

function search(arr){
  let left = 0;
  let right = arr.length - 1;

  while (left < right) {
    let mid = Math.floor((left + right) / 2);

    // If the middle element is odd, check the left half
    if (mid % 2 !== 0) {
      if (arr[mid] === arr[mid - 1]) {
        left = mid + 1;
      } else {
        right = mid;
      }
    } else {
      // If the middle element is even, check the right half
      if (arr[mid] === arr[mid + 1]) {
        left = mid + 2;
      } else {
        right = mid;
      }
    }
  }

  return arr[left];
}

