function Find_Min(lst){
    let minLength = Infinity;
    let minIndex = -1;
    for (let i = 0; i < lst.length; i++) {
        for (let j = i; j < lst.length; j++) {
            let subarray = lst.slice(i, j + 1);
            if (subarray.length < minLength) {
                minLength = subarray.length;
                minIndex = i;
            }
        }
    }
    return lst.slice(minIndex, minIndex + minLength);
}

function Find_Min(lst){
    let minLen = Infinity;
    let minSubarray = [];

    for (let i = 0; i < lst.length; i++) {
        let currentLen = 1;
        let currentSubarray = [lst[i]];

        for (let j = i + 1; j < lst.length; j++) {
            if (lst[j] === lst[i]) {
                currentLen++;
                currentSubarray.push(lst[j]);
            } else {
                break;
            }
        }

        if (currentLen < minLen) {
            minLen = currentLen;
            minSubarray = currentSubarray;
        }
    }

    return minSubarray;
}

