function k_smallest_pairs(nums1, nums2, k) {
  const minHeap = new MinHeap();
  for (const num1 of nums1) {
    for (const num2 of nums2) {
      if (minHeap.size() < k) {
        minHeap.push([num1, num2]);
      } else if (num1 + num2 < minHeap.peek()[0] + minHeap.peek()[1]) {
        minHeap.pop();
        minHeap.push([num1, num2]);
      }
    }
  }
  return minHeap.toArray().map(pair => pair.join(','));
}

function k_smallest_pairs(nums1, nums2, k) {
    const minHeap = new MinHeap();
    for (const num of nums1) {
        minHeap.push([num, nums2[0], 0]);
    }
    const result = [];
    while (result.length < k && !minHeap.isEmpty()) {
        const [num1, num2, index] = minHeap.pop();
        result.push([num1, num2]);
        if (index + 1 < nums2.length) {
            minHeap.push([num1, nums2[index + 1], index + 1]);
        }
    }
    return result;
}

