    a: 'c', e: 'g', i: 'k', o: 'q', u: 'w',
    A: 'C', E: 'G', I: 'K', O: 'Q', U: 'W'
  };

  return message.split('').map(char => {
    if (vowels.includes(char)) {
      const nextVowel = vowelsMap[char];
      const index = vowels.indexOf(char);
      const nextIndex = (index + 2) % vowels.length;
      return vowels[nextIndex];
    } else {
      return char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
    }
  }).join('');
}

function encode(message){
  const vowels = 'aeiouAEIOU';
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let encodedMessage = '';

  for (let char of message) {
    if (vowels.includes(char)) {
      const index = vowels.indexOf(char);
      let nextVowelIndex = (index + 2) % vowels.length;
      let nextVowel = vowels[nextVowelIndex];
      encodedMessage += alphabet[(alphabet.indexOf(char) + alphabet.indexOf(nextVowel)) % alphabet.length];
    } else {
      encodedMessage += char;
    }
  }

  return encodedMessage;
}

