function find_combinations(test_list){
  const combinations = [];
  function backtrack(start, currentSum, currentCombination) {
    if (currentSum === 0) {
      combinations.push([...currentCombination]);
      return;
    }
    for (let i = start; i < test_list.length; i++) {
      if (test_list[i] > currentSum) continue;
      currentCombination.push(test_list[i]);
      backtrack(i + 1, currentSum - test_list[i], currentCombination);
      currentCombination.pop();
    }
  }
  backtrack(0, 0, []);
  return combinations;
}

function find_combinations(test_list){
    const results = [];
    const recursive = (index, currentSum, currentCombination) => {
        if (index === test_list.length) {
            if (currentSum === 0) {
                results.push(currentCombination.slice());
            }
            return;
        }
        // Include the current element
        currentCombination.push(test_list[index]);
        recursive(index + 1, currentSum + test_list[index], currentCombination);
        // Exclude the current element
        currentCombination.pop();
        recursive(index + 1, currentSum, currentCombination);
    };
    recursive(0, 0, []);
    return results;
}

