function rearrange_bigger(n) {
    const digits = n.toString().split('');
    const length = digits.length;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    for (let i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of the found digit that is greater than it
            for (let j = length - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    // Swap the found digits
                    [digits[i], digits[j]] = [digits[j], digits[i]];
                    // Sort the remaining digits to the right of the swapped digit
                    const rightPart = digits.slice(i + 1).sort((a, b) => a - b);
                    // Combine the parts to form the next bigger number
                    return parseInt(digits.slice(0, i + 1).join('') + rightPart.join(''));
                }
            }
        }
    }

    // If no bigger number can be formed, return -1
    return -1;
}

function rearrange_bigger(n) {
  // Convert the number to an array of digits
  const digits = Array.from(String(n), Number);

  // Find the largest index i such that digits[i] < digits[i+1]
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such index exists, the number is the largest possible permutation
  if (i === -1) {
    return -1;
  }

  // Find the largest index j such that digits[j] > digits[i]
  let j = digits.length - 1;
  while (digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Reverse the digits from i+1 to the end
  digits.splice(i + 1).reverse();

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

function do_algebra(operator, operand) {
    let result = operand[0];
    for (let i = 0; i < operator.length; i++) {
        switch (operator[i]) {
            case '+':
                result += operand[i + 1];
                break;
            case '-':
                result -= operand[i + 1];
                break;
            case '*':
                result *= operand[i + 1];
                break;
            case '//':
                result = Math.floor(result / operand[i + 1]);
                break;
            case '**':
                result = Math.pow(result, operand[i + 1]);
                break;
            default:
                throw new Error(`Unsupported operator: ${operator[i]}`);
        }
    }
    return result;
}

