function sequence(n){
  if (n <= 0) return "Invalid input";
  if (n === 1) return 1;
  if (n === 2) return 1;

  const memo = new Map();
  memo.set(1, 1);
  memo.set(2, 1);

  function findNext(num) {
    if (memo.has(num)) return memo.get(num);
    const next = findNext(findNext(num - 1)) + findNext(num - 2);
    memo.set(num, next);
    return next;
  }

  return findNext(n);
}

