function rearrange_bigger(n) {
  let digits = Array.from(String(n), Number);
  let len = digits.length;
  let found = false;

  // Find the first digit from the right that is smaller than the digit immediately to its right
  for (let i = len - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      found = true;
      break;
    }
  }

  if (!found) {
    return -1; // No bigger number can be formed
  }

  // Find the smallest digit to the right of the found digit that is greater than it
  let j = len - 1;
  while (digits[j] <= digits[i]) {
    j--;
  }

  // Swap the digits
  let temp = digits[i];
  digits[i] = digits[j];
  digits[j] = temp;

  // Sort the digits to the right of the found digit in ascending order
  digits.splice(i + 1, len - i - 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  const digits = Array.from(String(n));
  const sortedDigits = digits.slice().sort((a, b) => b - a);

  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < sortedDigits[i]) {
      const j = sortedDigits.findIndex(digit => digit > digits[i]);
      [digits[i], digits[j]] = [digits[j], digits[i]];
      const rest = digits.slice(0, i).concat(sortedDigits.slice(i));
      return parseInt(rest.join(''));
    }
  }

  return -1; // No bigger number can be formed
}

