function get_total_number_of_sequences(m, n){
    if (m < 2) return 0;
    if (n === 1) return 1;
    let dp = new Array(n + 1).fill(0);
    dp[1] = 1;
    for (let i = 2; i <= n; i++) {
        for (let j = 2; j <= m; j++) {
            dp[i] += dp[i - 1];
        }
    }
    return dp[n];
}

function encode(message){
  const vowels = 'aeiouAEIOU';
  const shift = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ';
  let encodedMessage = '';

  for (let char of message) {
    if (vowels.includes(char)) {
      let index = vowels.indexOf(char);
      let shiftedIndex = (index + 2) % vowels.length;
      encodedMessage += shift[shiftedIndex];
    } else {
      encodedMessage += char;
    }
  }

  return encodedMessage;
}

