function rearrange_bigger(n) {
  const digits = Array.from(String(n), Number);
  const sortedDigits = [...digits].sort((a, b) => b - a);

  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < sortedDigits[i]) {
      const j = sortedDigits.indexOf(digits[i]);
      [digits[i], digits[j]] = [digits[j], digits[i]];
      const remainingDigits = digits.slice(0, i).concat(sortedDigits.slice(i + 1));
      return parseInt(remainingDigits.join(''));
    }
  }

  return -1; // No larger number can be formed
}

function rearrange_bigger(n){
    // Convert number to string to easily manipulate digits
    let digits = n.toString().split('');

    // Sort the digits in descending order to get the largest possible number
    digits.sort((a, b) => b - a);

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest possible number
    if (i < 0) {
        return -1; // No bigger number can be formed
    }

    // Find the smallest digit to the right of the found digit that is greater than it
    let j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    let temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the remaining digits in ascending order
    digits.splice(i + 1);
    digits.sort((a, b) => a - b);

    // Convert the digits back to a number and return
    return parseInt(digits.join(''));
}

