    const dp = Array.from({ length: n }, () => Array(n).fill(0));

    for (let i = 0; i < n; i++) {
        dp[i][i] = arr[i];
    }

    for (let len = 2; len <= n; len++) {
        for (let i = 0; i < n - len + 1; i++) {
            let j = i + len - 1;
            dp[i][j] = Math.max(arr[i], arr[j]);
            for (let k = i + 1; k < j; k++) {
