  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let prev = bell[i - 1];
    let newBell = [];
    for (let j = 0; j < prev.length; j++) {
      newBell.push(prev[j] * (i - 1));
    }
    for (let j = 0; j < prev.length; j++) {
      if (j < prev.length - 1) {
        newBell.push(prev[j] + prev[j + 1]);
      } else {
