function group_tuples(Input) {
  if (Input.length === 0) return null; // Return null if the input array is empty

  // Find the first element of the first array
  const firstElement = Input[0][0];

  // Check if all arrays have the same first element
  for (let i = 1; i < Input.length; i++) {
    if (Input[i][0] !== firstElement) return null; // Return null if any array has a different first element
  }

  return firstElement; // Return the common first element
}

