function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n - 1) {
    return a[index];
  }

  let maxSum = a[index];
  let maxSumIncludingK = a[index];

  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index]) {
      maxSum = Math.max(maxSum, maxSumIncludingK + a[i]);
    }
  }

  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index] && i > k) {
      maxSumIncludingK = Math.max(maxSumIncludingK, maxSum + a[i]);
    }
  }

  return Math.max(maxSum, maxSumIncludingK);
}

