function rearrange_bigger(n) {
  const digits = n.toString().split('').map(Number);
  let i = digits.length - 2;

  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  if (i === -1) {
    return -1; // No bigger number can be formed
  }

  let j = i + 1;
  while (j < digits.length && digits[j] > digits[i]) {
    j++;
  }

  [digits[i], digits[j]] = [digits[j], digits[i]];

  let left = digits.slice(0, i + 1);
  let right = digits.slice(i + 1).sort((a, b) => a - b);

  return parseInt(left.join('') + right.join(''));
}

function rearrange_bigger(n) {
  let digits = n.toString().split('');
  let sortedDigits = digits.slice().sort((a, b) => b - a);
  let index = 0;

  // Find the first digit from the right that is smaller than the digit to its right
  for (let i = digits.length - 1; i > 0; i--) {
    if (digits[i - 1] < digits[i]) {
      index = i - 1;
      break;
    }
  }

  // If no such digit is found, the number is the largest permutation
  if (index === -1) {
    return -1;
  }

  // Find the smallest digit to the right of index that is greater than digits[index]
  for (let i = digits.length - 1; i > index; i--) {
    if (digits[i] > digits[index]) {
      [digits[index], digits[i]] = [digits[i], digits[index]];
      break;
    }
  }

  // Sort the remaining digits to the right of index in ascending order
  digits.splice(index + 1).sort((a, b) => a - b);

  // Combine the sorted digits back into a number
  return parseInt(digits.join(''), 10);
}

