    // Check for all possible increasing subsequences ending at the current index
    for (let j = 0; j < i; j++) {
      if (a[j] < a[i] && dp[j] + a[i] > dp[i]) {
        dp[i] = dp[j] + a[i];
      }
    }
  }

  // Initialize variables to keep track of the maximum sum and the index of the kth element
  let maxSum = 0;
  let kIndex = -1;

  // Iterate through the DP array to find the maximum sum and the index of the kth element
  for (let i = 0; i < n; i++) {
    if (dp[i] > maxSum) {
      maxSum = dp[i];
      kIndex = i;
    }
  }

  // If k is greater than the index of the kth element, return the maximum sum
  if (k > kIndex) {
    return maxSum;
  }

  // If k is less than or equal to the index of the kth element, find the maximum sum of increasing subsequence including the kth element
  let result = 0;
  for (let i = 0; i <= kIndex; i++) {
    result = Math.max(result, dp[i] + a[k]);
  }

  // If k is greater than the index of the kth element, return the maximum sum of increasing subsequence including the kth element
  for (let i = kIndex + 1; i < n; i++) {
    result = Math.max(result, dp[i] + a[k]);
  }

  return result;
}

