function get_total_number_of_sequences(m, n){
    if (m < 2 || n < 1) {
        return 0;
    }

    let dp = new Array(n + 1).fill(0);
    dp[0] = 1; // There's one way to have an empty sequence

    for (let i = 1; i <= n; i++) {
        for (let j = 2 * i; j <= m; j++) {
            dp[i] += dp[j - 2 * i];
        }
    }

    return dp[n];
}

function get_total_number_of_sequences(m, n) {
    if (m < 2 || n < 1) {
        return 0;
    }

    const dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(0));

    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            if (i === 1) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = dp[i - 1][j] + (j - 1 >= 2 ? dp[i - 1][j - 1] : 0);
            }
        }
    }

    return dp[n][m];
}

