function max_sum_increasing_subseq(a, n, index, k) {
    const dp = new Array(n).fill(0);
    dp[index] = a[index];
    let maxSum = a[index];

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    for (let i = index + 1; i < k; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n) return 0;

  // Include the kth element if it is after the current index
  if (k > index) {
    return Math.max(
      a[index] + max_sum_increasing_subseq(a, n, index + 1, k),
      max_sum_increasing_subseq(a, n, index + 1, k)
    );
  }

  // Exclude the kth element
  return max_sum_increasing_subseq(a, n, index + 1, k);
}

