function Find_Min(lst){
  let minLength = Infinity;
  let minSubarray = [];

  for (let i = 0; i < lst.length; i++) {
    let currentLength = 1;
    let currentSubarray = [lst[i]];

    for (let j = i + 1; j < lst.length; j++) {
      if (lst[j] >= lst[i]) {
        currentLength++;
        currentSubarray.push(lst[j]);
      } else {
        break;
      }
    }

    if (currentLength < minLength) {
      minLength = currentLength;
      minSubarray = currentSubarray;
    }
  }

  return minSubarray;
}

function Find_Min(lst) {
  let minLength = Infinity;
  let startIndex = 0;

  for (let endIndex = 0; endIndex < lst.length; endIndex++) {
    let currentLength = endIndex - startIndex + 1;

    if (currentLength < minLength) {
      minLength = currentLength;
      startIndex = endIndex - minLength + 1;
    }
  }

  return lst.slice(startIndex, startIndex + minLength);
}

