function minPath(grid, k){
  const n = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
  const visited = new Array(n).fill().map(() => new Array(n).fill(false));
  const path = [];
  const minPathValues = [];

  function dfs(row, col, steps) {
    if (steps === k) {
      minPathValues.push([...path]);
      return;
    }

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;

      if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path.push(grid[newRow][newCol]);
        dfs(newRow, newCol, steps + 1);
        path.pop();
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      dfs(i, j, 0);
    }
  }

  minPathValues.sort((a, b) => {
    for (let i = 0; i < a.length && i < b.length; i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return a.length - b.length;
  });

  return minPathValues[0];
}

