function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n) return 0;

    let maxSum = 0;

    // Include the current element in the subsequence
    let currentSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            currentSum += a[i];
        }
    }

    // Exclude the current element from the subsequence
    let excludeCurrentSum = max_sum_increasing_subseq(a, n, index + 1, k);

    // Include the kth element in the subsequence
    if (k > index) {
        let kthSum = a[k];
        for (let i = k + 1; i < n; i++) {
            if (a[i] > a[k]) {
                kthSum += a[i];
            }
        }
        maxSum = Math.max(maxSum, currentSum + kthSum);
    }

    return Math.max(maxSum, excludeCurrentSum);
}

