            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny] && grid[nx][ny] !== targetValue) {
                visited[nx][ny] = true;
                path.push(grid[nx][ny]);
                dfs(nx, ny, steps + 1);
                path.pop();
                visited[nx][ny] = false;
            }
        }
    };

