function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

  function dfs(grid, x, y, path, count) {
    if (count === k) {
      return path;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !path.includes(grid[nx][ny])) {
        const newPath = [...path, grid[nx][ny]];
        const result = dfs(grid, nx, ny, newPath, count + 1);
        if (result) {
          return result;
        }
      }
    }

    return null;
  }

  let minPath = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const result = dfs(grid, i, j, [grid[i][j]], 1);
      if (result && (!minPath || result.length < minPath.length)) {
        minPath = result;
      }
    }
  }

  return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let minPathValues = [];

    const dfs = (x, y, steps) => {
        if (steps === k) {
            minPathValues.push(...grid[x][y]);
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, steps + 1);
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                dfs(i, j, 1);
                break;
            }
        }
    }

    return minPathValues;
}

