function find_combinations(test_list){
    let result = [];
    let currentCombination = [];
    let currentSum = 0;

    function backtrack(start) {
        if (currentSum === test_list.length) {
            result.push([...currentCombination]);
            return;
        }

        for (let i = start; i < test_list.length; i++) {
            currentCombination.push(test_list[i]);
            currentSum += test_list[i];
            backtrack(i + 1);
            currentCombination.pop();
            currentSum -= test_list[i];
        }
    }

    backtrack(0);
    return result;
}

function find_combinations(test_list){
    function combine(arr, n) {
        if (n === 0) {
            return [[]];
        }
        let result = [];
        for (let i = 0; i < arr.length; i++) {
            let current = arr[i];
            let subCombinations = combine(arr.slice(i + 1), n - 1);
            for (let j = 0; j < subCombinations.length; j++) {
                result.push([current].concat(subCombinations[j]));
            }
        }
        return result;
    }

    let combinations = [];
    for (let i = 1; i <= test_list.length; i++) {
        combinations = combinations.concat(combine(test_list, i));
    }

    return combinations;
}

