function rearrange_bigger(n){
  // Convert the number to an array of its digits
  const digits = Array.from(String(n), Number);

  // Sort the digits in descending order
  digits.sort((a, b) => b - a);

  // Find the largest index i such that digits[i] < digits[i + 1]
  let i = -1;
  for (let j = 0; j < digits.length - 1; j++) {
    if (digits[j] < digits[j + 1]) {
      i = j;
    }
  }

  // If no such index is found, return -1
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit greater than digits[i] to the right of i
  let j = i + 1;
  for (let k = j; k < digits.length; k++) {
    if (digits[k] > digits[i]) {
      j = k;
    }
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of i in ascending order
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  const digits = n.toString().split('').sort((a, b) => b - a);
  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      const j = digits.length - 1;
      while (digits[j] <= digits[i]) j--;
      [digits[i], digits[j]] = [digits[j], digits[i]];
      digits.splice(i + 1);
      digits.sort((a, b) => b - a);
      return parseInt(digits.join(''));
    }
  }
  return -1;
}

