function get_total_number_of_sequences(m, n) {
    if (m < 2 || n < 1) return 0;

    let dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(0));

    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            if (i === 1) {
                dp[i][j] = 1; // There's only one way to choose 1 element
            } else {
                dp[i][j] = dp[i - 1][j]; // No choice, stay the same
                if (j >= 2 * (i - 1)) {
                    dp[i][j] += dp[i - 1][j - 2 * (i - 1)]; // Choose 2 * (i - 1) elements
                }
            }
        }
    }

    return dp[n][m];
}

