    let dp = new Array(n + 1).fill(0);
    for (let i = index + 1; i <= k; i++) {
        dp[i] = a[i];
    }
    for (let i = index + 1; i <= k; i++) {
        for (let j = 0; j < i; j++) {
            if (a[i] > a[j]) {
                dp[i] = Math.max(dp[i], dp[j] + a[i]);
            }
        }
    }
    let maxSum = 0;
    for (let i = index + 1; i <= k; i++) {
        maxSum = Math.max(maxSum, dp[i]);
    }
    return maxSum;
