function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = new Map();
  memo.set(0, 0);
  memo.set(1, 1);

  function helper(n) {
    if (memo.has(n)) return memo.get(n);

    const result = helper(Math.floor(n / 2)) + helper(n % 2);
    memo.set(n, result);
    return result;
  }

  return helper(n);
}

