function Find_Min(lst){
  let minLen = Infinity;
  let minSubarray = [];

  for (let i = 0; i < lst.length; i++) {
    let currentLen = 1;
    let currentSubarray = [lst[i]];

    for (let j = i + 1; j < lst.length; j++) {
      if (lst[j] === lst[j - 1]) {
        currentLen++;
        currentSubarray.push(lst[j]);
      } else {
        break;
      }
    }

    if (currentLen < minLen) {
      minLen = currentLen;
      minSubarray = currentSubarray;
    }
  }

  return minSubarray;
}

function Find_Min(lst) {
    let minLength = Infinity;
    let startIndex = 0;

    for (let i = 0; i < lst.length; i++) {
        let sum = 0;
        for (let j = i; j < lst.length; j++) {
            sum += lst[j];
            if (sum >= 0 && j - i + 1 < minLength) {
                minLength = j - i + 1;
                startIndex = i;
            }
        }
    }

    return lst.slice(startIndex, startIndex + minLength);
}

