  for (let i = 1; i < arr.length; i++) {
    if (arr[i] < 0) {
      let temp = max_product;
      max_product = min_product;
      min_product = temp;
    }

    max_product = Math.max(arr[i], max_product * arr[i]);
    min_product = Math.min(arr[i], min_product * arr[i]);

    result = Math.max(result, max_product);
  }

  return result;
}

