function group_tuples(Input){
  if (!Input || Input.length === 0) return null;

  // Find the minimum length of the arrays in the input
  const minLength = Math.min(...Input.map(arr => arr.length));

  // Extract the first element from each array up to the minLength
  const commonElements = Input.map(arr => arr.slice(0, minLength).filter((el, index) => arr.every(arr2 => arr2 === el && arr2 !== arr[index])));

  // Return the first element that is common across all arrays
  return commonElements.length > 0 ? commonElements[0][0] : null;
}

function bell_number(n){
