function minPath(grid, k) {
    const N = grid.length;
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const minPathLength = Infinity;
    const minPathValues = [];

    const dfs = (i, j, pathLength, pathValues) => {
        if (pathLength === k) {
            if (pathValues.length < minPathLength || (pathValues.length === minPathLength && pathValues.join('') < minPathValues.join(''))) {
                minPathLength = pathLength;
                minPathValues = [...pathValues];
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const ni = i + dx;
            const nj = j + dy;
            if (ni >= 0 && ni < N && nj >= 0 && nj < N && !visited[ni][nj]) {
                visited[ni][nj] = true;
                dfs(ni, nj, pathLength + 1, [...pathValues, grid[ni][nj]]);
                visited[ni][nj] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, 1, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    return minPathValues;
}

