    let minPath = [];
    let minPathLength = Infinity;

    function dfs(x, y, path, length) {
        if (length === k) {
            if (length < minPathLength) {
                minPath = [...path];
                minPathLength = length;
            }
            return;
        }

        visited[x][y] = true;
        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;
            if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited[newX][newY]) {
                dfs(newX, newY, [...path, grid[newX][newY]], length + 1);
            }
        }
        visited[x][y] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

