function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a DP array to store the maximum sum of increasing subsequence ending at each index
    const dp = new Array(n).fill(0);

    // Base case: The maximum sum of increasing subsequence ending at index 0 is the element itself
    dp[0] = a[index];

    // Iterate through the array to fill the DP array
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            // Check if the current element is greater than the previous element and the current index is greater than the previous index
            if (a[i] > a[j] && i > j) {
                // Update the DP array with the maximum sum of increasing subsequence ending at the current index
                dp[i] = Math.max(dp[i], dp[j] + a[i]);
            }
        }
        // Check if the kth element is greater than the current index and the current index is greater than the previous index
        if (k > i && i > index) {
            // Update the DP array with the maximum sum of increasing subsequence ending at the current index including the kth element
            dp[i] = Math.max(dp[i], dp[k] + a[i]);
        }
    }

    // Return the maximum sum of increasing subsequence ending at the last index
    return dp[n - 1];
}

