function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const path = [];
    const minPathLength = Infinity;
    const minPathValues = [];

    const dfs = (x, y, steps) => {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPathValues = [...path];
            }
            return;
        }

        visited.add(`${x},${y}`);

        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;

            if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited.has(`${newX},${newY}`)) {
                path.push(grid[newX][newY]);
                dfs(newX, newY, steps + 1);
                path.pop();
            }
        }

        visited.delete(`${x},${y}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    return minPathValues;
}

function minPath(grid, k){
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const queue = [[grid[0][0], 0, 0]]; // [value, row, col]
  const minPath = [];
  let minLength = Infinity;

  while (queue.length > 0) {
    const [value, row, col] = queue.shift();

    if (minLength > k) {
      minLength = k;
      minPath = [value];
    } else if (minLength === k) {
      minPath.push(value);
    }

    if (value === k) {
      return minPath;
    }

    visited[row][col] = true;

    for (const [dx, dy] of directions) {
      const newRow = row + dy;
      const newCol = col + dx;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        queue.push([grid[newRow][newCol], newRow, newCol]);
      }
    }
  }

  return minPath;
}

