    function find_combinations_recursive(index, current_sum, current_combination) {
        // Base case: if the current combination sum equals the target sum
        if (current_sum === test_list[index]) {
            // Add the current combination to the result
            combinations.push([...current_combination]);
            return;
        }

        // If the current combination sum exceeds the target sum, stop the recursion
        if (current_sum > test_list[index]) {
            return;
        }

        // Iterate through the remaining elements in the array
