function bell_number(n) {
    // Helper function to calculate the Bell number
    function bell(n) {
        if (n === 0) return 1;
        let b = 1;
        for (let i = 1; i <= n; i++) {
            b = b * (n + i) / i;
        }
        return b;
    }

    // Calculate the number of ways to partition the set of Bell numbers
    let ways = 0;
    for (let i = 1; i <= n; i++) {
        ways += bell(i);
    }
    return ways;
}

