function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n + 1).fill(0);
    let prev = new Array(n + 1).fill(-1);

    for (let i = 0; i <= index; i++) {
        for (let j = i + 1; j <= n; j++) {
            if (a[i] < a[j] && dp[j] < dp[i] + a[j]) {
                dp[j] = dp[i] + a[j];
                prev[j] = i;
            }
        }
    }

    let maxSum = 0;
    let maxIndex = -1;

    for (let i = index + 1; i <= n; i++) {
        if (dp[i] > maxSum) {
            maxSum = dp[i];
            maxIndex = i;
        }
    }

    let result = maxSum + a[k];
    let current = k;
    while (current !== index) {
        current = prev[current];
        result += a[current];
    }

    return result;
}

