function find_combinations(test_list){
    // Helper function to calculate the sum of an array
    function sum(arr) {
        return arr.reduce((acc, val) => acc + val, 0);
    }

    // Helper function to generate all possible combinations of an array
    function combinations(arr, n) {
        if (n === 0) return [[]];
        if (arr.length === 0) return [];
        const result = [];
        for (let i = 0; i < arr.length; i++) {
            const current = arr[i];
            const rest = arr.slice(i + 1);
            const combinationsOfRest = combinations(rest, n - 1);
            for (const combination of combinationsOfRest) {
                result.push([current, ...combination]);
            }
        }
        return result;
    }

    // Generate all possible combinations of sums
    const sums = [];
    for (let i = 1; i <= test_list.length; i++) {
        const combinationsOfLengthI = combinations(test_list, i);
        for (const combination of combinationsOfLengthI) {
            sums.push(sum(combination));
        }
    }

    // Return the unique sums
    return [...new Set(sums)];
}

function find_combinations(test_list){
    const result = [];
    const backtrack = (index, currentSum, currentCombination) => {
        if (currentSum === 0) {
            result.push(currentCombination.slice());
            return;
        }
        if (index >= test_list.length || currentSum < 0) {
            return;
        }
        currentCombination.push(test_list[index]);
        backtrack(index + 1, currentSum - test_list[index], currentCombination);
        currentCombination.pop();
        backtrack(index + 1, currentSum, currentCombination);
    };
    backtrack(0, 0, []);
    return result;
}

