function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a DP array to store the maximum sum of increasing subsequence up to each index
  const dp = new Array(n).fill(0);

  // Iterate through the array to fill the DP array
  for (let i = index + 1; i < n; i++) {
    // Check if the current element is greater than the previous element
    if (a[i] > a[index]) {
      // Update the maximum sum for the current index
      dp[i] = Math.max(dp[i], dp[index] + a[i]);
    }
  }

  // Initialize a DP array to store the maximum sum of increasing subsequence including the kth element
  const dp_with_k = new Array(n).fill(0);

  // Iterate through the array to fill the DP array including the kth element
  for (let i = 0; i < n; i++) {
    // Check if the current element is greater than the previous element and the kth element is after the current index
    if (a[i] > a[index] && i < k) {
      // Update the maximum sum for the current index including the kth element
      dp_with_k[i] = Math.max(dp_with_k[i], dp[i] + a[i]);
    }
  }

  // Return the maximum sum of increasing subsequence including the kth element
  return Math.max(...dp_with_k);
}

