  const max_product_at_index = new Array(arr.length).fill(1);
  // Initialize an array to store the maximum product ending at each index, considering the previous maximum
  const max_product_at_index_with_prev_max = new Array(arr.length).fill(1);

  // Iterate through the array to find the maximum product ending at each index
  for (let i = 1; i < arr.length; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && max_product_at_index[j] > 0) {
        max_product_at_index[i] = Math.max(max_product_at_index[i], max_product_at_index[j] * arr[i]);
      }
      if (arr[i] > arr[j] && max_product_at_index_with_prev_max[j] > 0) {
        max_product_at_index_with_prev_max[i] = Math.max(max_product_at_index_with_prev_max[i], max_product_at_index_with_prev_max[j] * arr[i]);
