function occurance_substring(text, pattern) {
    let matches = [];
    let index = text.indexOf(pattern);

    while (index !== -1) {
        matches.push({ index: index, count: 1 });
        index = text.indexOf(pattern, index + 1);
    }

    return matches;
}

function occurance_substring(text, pattern) {
  if (!text || !pattern) return undefined;

  let occurrences = [];
  let index = 0;

  while ((index = text.indexOf(pattern, index)) !== -1) {
    occurrences.push({ position: index, count: 1 });
    index++;
  }

  return occurrences;
}

