function find_length(string){
    let maxLength = 0;
    let count0 = 0;
    let count1 = 0;
    let start = 0;

    for(let i = 0; i < string.length; i++){
        if(string[i] === '0'){
            count0++;
        } else {
            count1++;
        }

        if(count0 === count1){
            maxLength = Math.max(maxLength, i - start + 1);
        } else if(count0 > count1){
            maxLength = Math.max(maxLength, i - start + 1);
            start = i - count0 + 1;
        } else {
            start = i - count1 + 1;
        }
    }

    return maxLength;
}

function find_length(string) {
