    if (string[i] === '0') {
      zeroCount++;
    } else {
      oneCount++;
    }

    let currentDiff = Math.abs(zeroCount - oneCount);
    if (currentDiff > maxDiff) {
      maxDiff = currentDiff;
    }
  }

  return maxDiff;
}

