function generate_integers(a, b) {
  // Ensure a is less than or equal to b
  if (a > b) {
    [a, b] = [b, a];
  }

  // Initialize an empty array to store even digits
  const evenDigits = [];

  // Loop through each digit from a to b
  for (let i = a; i <= b; i++) {
    // Convert the current digit to a string to easily access each character
    const str = i.toString();

    // Loop through each character of the string
    for (let j = 0; j < str.length; j++) {
      // Check if the character is an even digit
      if (parseInt(str[j]) % 2 === 0) {
        // Add the even digit to the array
        evenDigits.push(parseInt(str[j]));
      }
    }
  }

  // Return the array of even digits in ascending order
  return evenDigits.sort((a, b) => a - b);
}

function generate_integers(a, b){
  // Ensure a is always less than or equal to b
  if(a > b) {
    const temp = a;
    a = b;
    b = temp;
  }

  // Filter even digits between a and b
  const evenDigits = Array.from({ length: b - a + 1 }, (_, i) => a + i)
                         .filter(digit => digit % 2 === 0);

  // Sort the even digits in ascending order
  evenDigits.sort((a, b) => a - b);

  return evenDigits;
}

