function group_tuples(Input) {
    // Check if the input is an array of arrays
    if (!Array.isArray(Input) || Input.length === 0) {
        throw new Error('Input must be an array of arrays');
    }

    // Find the minimum length of the arrays
    const minLength = Math.min(...Input.map(arr => arr.length));

    // Initialize an empty array to store the common elements
    const commonElements = [];

    // Iterate through the first array to find common elements
    for (let i = 0; i < minLength; i++) {
        // Check if the current element is present in all other arrays
        if (Input.every(arr => arr[i] === Input[0][i])) {
            commonElements.push(Input[0][i]);
        }
    }

    return commonElements;
}

function group_tuples(Input){
    // Find the intersection of all arrays in the input
    const intersection = Input.reduce((acc, curr) => {
        return acc.filter(item => curr.includes(item));
    }, Input[0]);

    // Return the first element of the intersection
    return intersection[0];
}

