function min_Jumps(steps, d) {
  // Initialize the current position and the number of jumps
  let position = 0;
  let jumps = 0;

  // Iterate until the current position is greater than or equal to the target position
  while (position < d) {
    // Calculate the maximum distance that can be reached in one jump
    let maxJump = Math.min(steps, d - position);

    // Update the current position by adding the maximum jump
    position += maxJump;

    // Increment the number of jumps
    jumps++;
  }

  // Return the total number of jumps required
  return jumps;
}

