function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index including the kth element
    const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => 0));

    // Iterate through the array to fill the dp table
    for (let i = 0; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            // If the current element is greater than the previous element and the current index is greater than or equal to the previous index
            if (a[i] > a[j - 1] && i >= j - 1) {
                // Update the dp table with the maximum sum of increasing subsequence up to the current index including the kth element
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            } else {
                // If the current element is not greater than the previous element or the current index is less than the previous index, keep the previous value
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    // The maximum sum of increasing subsequence up to the last index including the kth element is stored in dp[n - 1][k]
    return dp[n - 1][k];
}

