        for (let j = 0; j < n; j++) {
            if (i !== j) {
                dp[i][j] = arr[i] * arr[j];
                for (let k = 0; k < i; k++) {
                    dp[i][j] = Math.max(dp[i][j], dp[k][j] * arr[i]);
                }
                for (let k = 0; k < j; k++) {
