function bell_number(n) {
  if (n === 0) return 1;

  let bell = Array(n + 1).fill(0);
  bell[0] = 1;
  bell[1] = 1;

  for (let i = 2; i <= n; i++) {
    for (let j = i; j >= 1; j--) {
      bell[i] += bell[j - 1] * bell[i - j];
    }
  }

  return bell[n];
}

function bell_number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

