function group_tuples(Input){
  // Sort each array within the input array
  Input.sort((a, b) => a[0] - b[0]);

  // Initialize pointers for the first and second arrays
  let i = 0;
  let j = 1;

  // Loop through the sorted arrays
  while (j < Input.length) {
    // If the current elements are the same, move the second pointer forward
    if (Input[i][0] === Input[j][0]) {
      j++;
    } else {
      // If the current elements are different, return the first element of the current array
      return Input[i][0];
    }
    // Move the first pointer forward
    i++;
  }

  // If no common element is found, return null
  return null;
}

