function tri(n){
  if(n === 0) return [];
  if(n === 1) return [1];
  if(n === 2) return [1, 3];
  if(n === 3) return [1, 3, 2, 8];

  let sequence = [1, 3, 2, 8];
  for(let i = 4; i <= n; i++){
    if(i % 2 === 0){
      sequence.push(sequence[i - 2] + sequence[i - 1]);
    } else {
      let nextNumber = sequence[i - 1] + sequence[i - 2] + sequence[i + 1];
      sequence.push(nextNumber);
    }
  }
  return sequence;
}

