    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i === -1) {
        return -1; // No bigger number can be formed
    }
    let j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    [digits[i], digits[j]] = [digits[j], digits[i]];
    let left = digits.slice(0, i + 1);
    let right = digits.slice(i + 1).sort((a, b) => a - b);
    return parseInt([...left, ...right].join(''));
}

function rearrange_bigger(n) {
  // Convert the number to an array of digits
  let digits = Array.from(String(n), Number);

  // Find the index of the largest digit to the right of the current digit
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is the largest possible
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit to the right of the current digit that is greater than the digit at index i
  let j = digits.length - 1;
  while (j >= 0 && digits[j] <= digits[i]) {
    j--;
  }

  // Swap the digits at index i and j
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of index i
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

