  const bell = new Array(n + 1).fill(0);
  bell[0] = 1;

  // Calculate the bell numbers using dynamic programming
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      bell[i] += bell[j] * bell[i - j - 1];
    }
  }

  return bell[n];
}

