  if (n === 1) return 1;
  let bell = [0, 1];
  for (let i = 2; i <= n; i++) {
    let prev = bell[i - 1];
    let next = 0;
    for (let j = 0; j < i; j++) {
      next += prev * bell[j];
      prev = bell[j];
    }
    bell.push(next);
  }
  return bell[n];
}

