function get_total_number_of_sequences(m, n) {
  // Base case: If n is 1, there's only one sequence (the number itself).
  if (n === 1) return 1;

  // Initialize an array to store the number of sequences of length i for all i from 1 to n.
  const dp = new Array(n + 1).fill(0);
  dp[1] = 1; // There's only one sequence of length 1, which is the number itself.

  // Fill the dp array.
  for (let i = 2; i <= n; i++) {
    for (let j = i; j <= m; j++) {
      dp[i] += dp[i - 1];
    }
  }

  // The total number of sequences of length n is the last element in the dp array.
  return dp[n];
}

