function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (row, col, pathLength, path) => {
        if (pathLength === k) {
            if (pathLength < minPathLength) {
                minPathLength = pathLength;
                minPath = [...path];
            }
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
            return;
        }

        visited[row][col] = true;
        path.push(grid[row][col]);

        for (const [dx, dy] of directions) {
            dfs(row + dx, col + dy, pathLength + 1, path);
        }

        path.pop();
        visited[row][col] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const result = [];

    const dfs = (x, y, path, step) => {
        if (step === k) {
            result.push(path.slice());
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, path.concat(grid[nx][ny]), step + 1);
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    result.sort((a, b) => {
        for (let i = 0; i < Math.min(a.length, b.length); i++) {
            if (a[i] !== b[i]) return a[i] - b[i];
