}

function max_product(arr) {
  // Sort the array in ascending order
  arr.sort((a, b) => a - b);

  // Initialize variables to store the maximum product and the current product
  let maxProduct = arr[0];
  let currentProduct = arr[0];

  // Iterate through the sorted array to find the maximum product of increasing subsequences
  for (let i = 1; i < arr.length; i++) {
    // If the current element is greater than the last element of the current product, update the current product
    if (arr[i] > currentProduct) {
      currentProduct *= arr[i];
      maxProduct = Math.max(maxProduct, currentProduct);
    } else {
      // If the current element is less than or equal to the last element of the current product, start a new subsequence
      currentProduct = arr[i];
    }
  }

  return maxProduct;
}

