function max_sum_increasing_subseq(a, n, index, k) {
    const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => -Infinity));

    for (let i = index; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            if (j === 1) {
                dp[i][j] = a[i];
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1] + a[i]);
            }
        }
    }

    let result = -Infinity;
    for (let j = 1; j <= k; j++) {
        result = Math.max(result, dp[n - 1][j]);
    }

    return result;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n) {
        return 0;
    }

    // Include the kth element if it exists and is after the current index
    let includedK = 0;
    if (k < n && k > index) {
        includedK = a[k];
    }

    // Calculate the maximum sum including the kth element
    let includeK = a[index] + max_sum_increasing_subseq(a, n, index + 1, k);

    // Calculate the maximum sum excluding the kth element
    let excludeK = max_sum_increasing_subseq(a, n, index + 1, k);

    // Return the maximum of including or excluding the kth element
    return Math.max(includeK, excludeK);
}

