  for (let i = 1; i <= limit; i++) {
    let sumDivisors = 1; // Start with 1 because 1 is always a divisor
    for (let j = 2; j * j <= i; j++) {
      if (i % j === 0) {
        sumDivisors += j;
        if (j !== i / j) { // Avoid adding the square root twice for perfect squares
          sumDivisors += i / j;
