}

function get_total_number_of_sequences(m, n) {
  if (n === 0) {
    return 1; // There's one way to have no elements (the empty sequence).
  }

  if (n === 1) {
    return m; // There are m possible sequences of length 1.
  }

  let total = 0;
  for (let i = 2; i <= m; i++) {
