function rearrange_bigger(n) {
  // Convert the number to an array of digits
  const digits = Array.from(String(n), Number);

  // Start from the second last digit
  for (let i = digits.length - 2; i >= 0; i--) {
    // Find the first digit that is smaller than the current digit
    if (digits[i] < digits[i + 1]) {
      // Find the largest digit to the right of the current digit
      let j = digits.length - 1;
      while (digits[j] <= digits[i]) {
        j--;
      }

      // Swap the found digits
      [digits[i], digits[j]] = [digits[j], digits[i]];

      // Sort the remaining digits in descending order
      digits.slice(i + 1).sort((a, b) => b - a);

      // Convert the array of digits back to a number
      return parseInt(digits.join(''));
    }
  }

  // If no bigger number is found, return -1
  return -1;
}

function rearrange_bigger(n) {
  // Convert the number to an array of digits
  const digits = n.toString().split('').map(Number);

  // Find the first digit from the right that is smaller than the digit immediately to its right
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is already the largest permutation
  if (i === -1) {
    return -1; // Return -1 if no bigger number can be formed
  }

  // Find the smallest digit on the right side of i that is larger than digits[i]
  let j = digits.length - 1;
  while (j > i && digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of i in ascending order
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

