function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const pq = new PriorityQueue((a, b) => {
        for (let i = 0; i < k; i++) {
            if (a[i] !== b[i]) return a[i] - b[i];
        }
        return 0;
    });

    const start = [0, 0];
    visited.add(start.toString());
    pq.enqueue([grid[start[0]][start[1]], [start[0], start[1]]]);

    while (!pq.isEmpty()) {
        const [dist, cell] = pq.dequeue();
        const [row, col] = cell;

        if (dist === k) {
            return cell;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited.has(newRow.toString() + newCol.toString())) {
                visited.add(newRow.toString() + newCol.toString());
                pq.enqueue([dist + 1, [newRow, newCol]]);
            }
        }
    }

    return null;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const path = [];
    let minPathLength = Infinity;
    let minPathValues = [];

    function dfs(row, col, steps) {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPathValues = [...path];
            }
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
            return;
        }

        path.push(grid[row][col]);
        visited[row][col] = true;

        for (const [dr, dc] of directions) {
            dfs(row + dr, col + dc, steps + 1);
        }

        path.pop();
        visited[row][col] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    return minPathValues;
}

