  const bell = [0, 1, 1, 2, 5, 15, 52, 156, 429, 1386];

  // Check if the input n is less than or equal to the length of the bell array
  if (n <= bell.length) {
    return bell[n];
  }

  // If n is greater than the length of the bell array, calculate it using the recursive formula
  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += bell[i] * bell[n - i];
  }
  return result;
}

