function bell_number(n){
  // Base case: B(0) = 1
  if (n === 0) return 1;

  // Initialize the Bell numbers array
  const bell = new Array(n + 1).fill(0);
  bell[0] = 1;

  // Calculate Bell numbers using the recursive formula
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      bell[i] += bell[j] * bell[i - j - 1];
    }
  }

  return bell[n];
}

