function minPath(grid, k){
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
  const path = new Array(k);
  const minPathValue = Infinity;
  const minPathIndex = -1;

  function dfs(x, y, steps, currentPath) {
    if (steps === k) {
      if (currentPath < minPathValue) {
        minPathValue = currentPath;
        minPathIndex = currentPath;
      }
      return;
    }

    if (x < 0 || x >= N || y < 0 || y >= N || visited[x][y]) {
      return;
    }

    visited[x][y] = true;
    currentPath.push(grid[x][y]);

    for (const [dx, dy] of directions) {
      dfs(x + dx, y + dy, steps + 1, currentPath);
    }

    currentPath.pop();
    visited[x][y] = false;
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 0, []);
    }
  }

  return minPathIndex !== -1 ? minPath : [];
}

function minPath(grid, k) {
    const n = grid.length;
    const directions = [
        [0, 1], [1, 0], [0, -1], [-1, 0]
    ];
    const visited = new Array(n).fill().map(() => new Array(n).fill(false));
    const minPathLength = Infinity;
    const minPath = [];

    function dfs(x, y, steps, path) {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPath = [...path];
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, steps + 1, [...path, grid[nx][ny]]);
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            visited[i][j] = true;
            dfs(i, j, 1, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    return minPath;
}

