      // and sequences of length i-1 with elements greater than or equal to j/2 but less than or equal to m
      dp[i][j] = dp[i-1][j/2] + dp[i-1][Math.min(j, m)];
    }
  }

  // The total number of sequences of length n is the sum of sequences of length n with any element
  return dp[n][m];
}

