function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a 2D array to store the maximum sum of increasing subsequence
  const dp = new Array(n).fill(0).map(() => new Array(k + 1).fill(0));

  // Fill the dp array
  for (let i = 0; i < n; i++) {
    for (let j = 1; j <= k; j++) {
      if (i === 0 || a[i] <= a[j - 1]) {
        dp[i][j] = dp[i - 1][j];
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
      }
    }
  }

  // Return the maximum sum of increasing subsequence including the given kth element
  return dp[n - 1][k];
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n - 1) {
    return a[index];
  }

  let maxSum = a[index];
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index] && i > k) {
      maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
    }
  }

  return maxSum;
}

function max_product(arr) {
  let n = arr.length;
  let dp = Array.from({ length: n }, () => Array(n).fill(0));

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) {
        dp[i][j] = arr[i];
      } else if (arr[i] < arr[j]) {
        dp[i][j] = Math.max(arr[i], dp[i][j - 1]);
      } else if (arr[i] > arr[j]) {
        dp[i][j] = Math.max(arr[j], dp[i - 1][j]);
      } else {
        dp[i][j] = Math.max(arr[i], arr[j], dp[i - 1][j - 1]);
      }
    }
  }

  let maxProduct = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      maxProduct = Math.max(maxProduct, dp[i][j] * arr[i] * arr[j]);
    }
  }

  return maxProduct;
}

