            if (currentSum === 0) {
                result.push(path.slice());
            }
            return;
        }
        // Include the current element
        path.push(test_list[index]);
        backtrack(index + 1, currentSum + test_list[index], path);
        // Exclude the current element
        path.pop();
        backtrack(index + 1, currentSum, path);
    };
    backtrack(0, 0, []);
    return result;
