function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = new Array(k + 1).fill(0);
  const result = [];

  function dfs(row, col, steps) {
    if (steps === k) {
      result.push(path.slice());
      return;
    }

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path[steps] = grid[newRow][newCol];
        dfs(newRow, newCol, steps + 1);
        path[steps] = 0;
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      path[0] = grid[i][j];
      dfs(i, j, 1);
      path[0] = 0;
      visited[i][j] = false;
    }
  }

  result.sort((a, b) => {
    for (let i = 0; i < k; i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return 0;
  });

  return result[0];
}

