        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !path.includes(grid[nx][ny])) {
                dfs(nx, ny, [...path, grid[nx][ny]], steps + 1);
