        // If the current digit is less than the digit next to it
        if (str[i] < str[i + 1]) {
            // Find the smallest digit to the right of the current digit that is greater than it
            for (let j = len - 1; j > i; j--) {
                if (str[j] > str[i]) {
                    // Swap the digits
