function find_combinations(test_list) {
    const results = [];
    const backtrack = (index, currentSum, currentCombination) => {
        if (currentSum === test_list.length) {
            results.push([...currentCombination]);
            return;
        }
        for (let i = index; i < test_list.length; i++) {
            currentCombination.push(test_list[i]);
            backtrack(i + 1, currentSum + test_list[i], currentCombination);
            currentCombination.pop();
        }
    };
    backtrack(0, 0, []);
    return results;
}

function find_combinations(test_list) {
  const result = [];

  // Helper function to generate combinations
  function generate_combinations(arr, index, sum, current_combination) {
    if (index === arr.length) {
      if (sum === 0) {
        result.push(current_combination.slice());
      }
      return;
    }

    // Include the current element
    current_combination.push(arr[index]);
    generate_combinations(arr, index + 1, sum - arr[index], current_combination);

    // Exclude the current element
    current_combination.pop();
    generate_combinations(arr, index + 1, sum, current_combination);
  }

  generate_combinations(test_list, 0, 0, []);

  return result;
}

