function get_total_number_of_sequences(m, n) {
    if (n === 1) return 1; // Only one sequence of length 1 is possible
    if (n > m) return 0; // No sequences possible if n is greater than m

    let dp = new Array(m + 1).fill(0);
    dp[0] = 1; // There is one way to have a sequence of length 0 (the empty sequence)

    for (let i = 1; i <= m; i++) {
        for (let j = i; j <= m; j++) {
            if (j >= 2 * i) {
                dp[j] += dp[i - 1];
            }
        }
    }

    return dp[m];
}

function get_total_number_of_sequences(m, n) {
  // Initialize a 2D array to store the number of sequences of length i with a maximum value of j
  const dp = new Array(n + 1).fill(0).map(() => new Array(m + 1).fill(0));

  // Base case: There is exactly one sequence of length 1 with any value
  for (let j = 1; j <= m; j++) {
    dp[1][j] = 1;
  }

  // Fill the dp array
  for (let i = 2; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      for (let k = 2; k <= j; k++) {
        dp[i][j] += dp[i - 1][k - 1];
      }
    }
  }

  // The total number of sequences of length n with a maximum value of m
  return dp[n][m];
}

