function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n).fill(0);
    let prev = new Array(n).fill(-1);

    for (let i = 0; i < n; i++) {
        dp[i] = a[i];
        prev[i] = -1;
    }

    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (a[i] > a[j] && dp[i] < dp[j] + a[i]) {
                dp[i] = dp[j] + a[i];
                prev[i] = j;
            }
        }
    }

    let maxSum = 0;
    let maxIndex = -1;

    for (let i = n - 1; i >= index; i--) {
        if (dp[i] > maxSum) {
            maxSum = dp[i];
            maxIndex = i;
        }
    }

    let sum = a[maxIndex];
    let currIndex = maxIndex;

    while (currIndex !== -1) {
        sum += a[prev[currIndex]];
        currIndex = prev[currIndex];
    }

    return sum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n) return 0;
    if (index === n - 1) return a[index];

    let maxSum = max_sum_increasing_subseq(a, n, index + 1, k);
    let sumIncludingK = 0;
    if (k < n && a[k] > a[index]) {
        sumIncludingK = a[index] + max_sum_increasing_subseq(a, n, k + 1, k);
    }

    return Math.max(maxSum, sumIncludingK);
}

