}

function k_smallest_pairs(nums1, nums2, k) {
  // Sort both arrays to facilitate the use of a min-heap
  nums1.sort((a, b) => a - b);
  nums2.sort((a, b) => a - b);

  // Initialize the heap with the first pair
  const minHeap = [nums1[0] + nums2[0]];
  const result = [];

  // Use a set to keep track of visited pairs to avoid duplicates
  const visited = new Set();

  // Process the heap
  while (minHeap.length < k && nums1.length > 0 && nums2.length > 0) {
    const pair = minHeap.shift();
    const [num1, num2] = pair.split(' ').map(Number);

    // Add the current pair to the result
    result.push(pair);

    // Add the next pair from the same array
    if (nums1.length > 1 && !visited.has(`${num1 + 1} ${num2}`)) {
      minHeap.push(`${num1 + 1} ${num2}`);
      visited.add(`${num1 + 1} ${num2}`);
    }

    // Add the next pair from the other array
    if (nums2.length > 1 && !visited.has(`${num1} ${num2 + 1}`)) {
      minHeap.push(`${num1} ${num2 + 1}`);
      visited.add(`${num1} ${num2 + 1}`);
    }
  }

  return result;
}

