function is_polite(n) {
  let polite = 1;
  while (true) {
    let sumOfDivisors = 1 + n;
    for (let i = 2; i <= Math.sqrt(sumOfDivisors); i++) {
      if (sumOfDivisors % i === 0) {
        sumOfDivisors += sumOfDivisors / i;
      }
    }
    if (sumOfDivisors === 2 * n) {
      return polite;
    }
    polite++;
  }
}

