function maximize_elements(test_tup1, test_tup2){
    // Create a copy of the tuples to avoid modifying the original arrays
    const tuple1 = [...test_tup1];
    const tuple2 = [...test_tup2];

    // Sort the tuples in descending order
    tuple1.sort((a, b) => b - a);
    tuple2.sort((a, b) => b - a);

    // Create a new array to store the maximum elements
    const result = [];

    // Iterate through the tuples and push the maximum elements to the result array
    for(let i = 0; i < Math.min(tuple1.length, tuple2.length); i++){
        result.push(Math.max(tuple1[i], tuple2[i]));
    }

    // If there are any remaining elements in either tuple, push them to the result array
    if(tuple1.length > tuple2.length){
        result.push(...tuple1.slice(tuple2.length));
    } else if(tuple2.length > tuple1.length){
        result.push(...tuple2.slice(tuple1.length));
    }

    return result;
}

