  const isAmicable = (num) => {
    let sum = 1;
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        sum += i + num / i;
      }
    }
    return sum === num && num !== sum ? true : false;
  };

  let sum = 0;
  for (let i = 2; i <= limit; i++) {
    if (isAmicable(i)) {
      sum += i;
    }
  }

  return sum;
}

