function bell_Number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let newBell = [];
    for (let j = 0; j <= i; j++) {
      if (j === 0 || j === i) {
        newBell.push(bell[j]);
      } else {
        newBell.push(bell[j - 1] + bell[j]);
      }
    }
    bell = newBell;
  }
  return bell[n];
}

function bell_Number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

function find_adverb_position(text) {
