}

function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    const visited = new Set();
    const path = [];

    function dfs(row, col, steps){
        if (steps === k) {
            path.push(...grid[row][col]);
            return;
        }

        for (const [dx, dy] of directions) {
            const newRow = row + dy;
            const newCol = col + dx;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                dfs(newRow, newCol, steps + 1);
                visited.delete(`${newRow},${newCol}`);
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited.add(`${i},${j}`);
            dfs(i, j, 1);
            visited.delete(`${i},${j}`);
        }
    }

    path.sort((a, b) => a - b);
    return path;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];

  function dfs(x, y, steps) {
    if (steps === k) {
      path.push(grid[x][y]);
      return;
    }
    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, steps + 1);
        visited[nx][ny] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  path.sort((a, b) => a - b);
  return path;
}

