function rearrange_bigger(n) {
    // Convert the number to a string to manipulate its digits
    let str = n.toString();
    let length = str.length;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = length - 2;
    while (i >= 0 && str[i] >= str[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest possible permutation
    if (i === -1) {
        return -1; // No bigger number exists
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j = length - 1;
    while (j >= 0 && str[j] <= str[i]) {
        j--;
    }

    // Swap the found digits
    [str[i], str[j]] = [str[j], str[i]];

    // Sort the remaining digits to the right of the swapped digit in ascending order
    let rightPart = str.substring(i + 1).split('').sort().join('');

    // Combine the parts to form the next bigger number
    return parseInt(str.substring(0, i + 1) + rightPart);
}

function rearrange_bigger(n) {
    const digits = n.toString().split('');
    let i = digits.length - 2;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        // If no such digit is found, the number is the largest possible permutation
        return -1;
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j = i + 1;
    for (; j < digits.length; j++) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of the found digit in ascending order
    digits.splice(i + 1).sort((a, b) => a - b);

    // Combine the digits back into a single number
    return parseInt(digits.join(''), 10);
}

