function minPath(grid, k) {
  const N = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathLength = Infinity;
  const minPath = [];

  const dfs = (row, col, steps) => {
    if (steps === k) {
      if (path.length < minPathLength || (path.length === minPathLength && path.join(',') < minPath.join(','))) {
        minPath = [...path];
        minPathLength = path.length;
      }
      return;
    }

    if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
      return;
    }

    visited[row][col] = true;
    path.push(grid[row][col]);

    for (const [dr, dc] of directions) {
      dfs(row + dr, col + dc, steps + 1);
    }

    path.pop();
    visited[row][col] = false;
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 1);
    }
  }

  return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    const visited = new Set();
    const path = [];
    const minPath = [];

    function dfs(x, y, steps) {
        if (steps === k) {
            minPath.push(...path);
            return;
        }

        if (visited.has(`${x},${y}`)) return;

        visited.add(`${x},${y}`);
        path.push(grid[x][y]);

        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;

            if (newX >= 0 && newX < N && newY >= 0 && newY < N) {
                dfs(newX, newY, steps + 1);
            }
        }

        path.pop();
        visited.delete(`${x},${y}`);
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1);
        }
    }

    minPath.sort((a, b) => a - b);
    return minPath;
}

