function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = new Map();
  memo.set(0, 0);
  memo.set(1, 1);

  function findNext(n) {
    if (memo.has(n)) return memo.get(n);

    const a = findNext(Math.floor(n / 2));
    const b = findNext(n % 2);
    const next = a + b;
    memo.set(n, next);
    return next;
  }

  return findNext(n);
}

