function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
    const path = [];
    const directionsCount = directions.length;

    function dfs(row, col, steps) {
        if (steps === k) {
            path.push(grid[row][col]);
            return;
        }

        visited[row][col] = true;
        for (let i = 0; i < directionsCount; i++) {
            const newRow = row + directions[i][0];
            const newCol = col + directions[i][1];
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                dfs(newRow, newCol, steps + 1);
            }
        }
        visited[row][col] = false;
    }

    let minPathValue = Infinity;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            dfs(i, j, 0);
            if (path.length >= k && path.slice(0, k).join('') < minPathValue.join('')) {
                minPathValue = path.slice(0, k);
            }
            path.pop();
        }
    }

    return minPathValue;
}

function minPath(grid, k){
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const n = grid.length;
  const m = grid[0].length;
  const visited = Array.from({ length: n }, () => Array(m).fill(false));
  const minPathValues = [];

  const dfs = (i, j, pathLength, path) => {
    if (pathLength === k) {
      minPathValues.push([...path]);
      return;
    }

    for (const [dx, dy] of directions) {
      const x = i + dx;
      const y = j + dy;

      if (x >= 0 && x < n && y >= 0 && y < m && !visited[x][y]) {
        visited[x][y] = true;
        dfs(x, y, pathLength + 1, [...path, grid[x][y]]);
        visited[x][y] = false;
      }
    }
  };

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      dfs(i, j, 1, [grid[i][j]]);
    }
  }

  // Sorting the minimum path values lexicographically
  minPathValues.sort((a, b) => {
    for (let i = 0; i < a.length && i < b.length; i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return a.length - b.length;
  });

  return minPathValues[0];
}

