function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = new Map();
  memo.set(0, 0);
  memo.set(1, 1);

  function helper(i) {
    if (memo.has(i)) return memo.get(i);

    const result = helper(i - 1) + helper(i - 2);
    memo.set(i, result);
    return result;
  }

  return helper(n);
}

