function minPath(grid, k) {
    let n = grid.length;
    let paths = [];

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            let path = [grid[i][j]];
            let queue = [[i, j, path]];
            let visited = new Set();

            while (queue.length > 0) {
                let [row, col, currPath] = queue.shift();
                if (currPath.length === k) {
                    paths.push(currPath);
                    continue;
                }

                let directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

                for (let [dr, dc] of directions) {
                    let newRow = row + dr;
                    let newCol = col + dc;

                    if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited.has(`${newRow},${newCol}`)) {
                        visited.add(`${newRow},${newCol}`);
                        let newPath = [...currPath, grid[newRow][newCol]];
                        queue.push([newRow, newCol, newPath]);
                    }
                }
            }
        }
    }

    // Find the minimum path in terms of lexicographical order
    let minPath = paths.reduce((acc, path) => {
        return path.join(',') < acc.join(',') ? path : acc;
    }, paths[0]);

    return minPath.map(Number);
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const paths = [];

  const dfs = (x, y, path, steps) => {
    if (steps === k) {
      paths.push(path.slice());
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, path.concat(grid[nx][ny]), steps + 1);
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, [grid[i][j]], 1);
    }
  }

  paths.sort((a, b) => {
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return a.length - b.length;
  });

  return paths[0];
}

