        r = (r * r) % num;
        if (r === 0) {
            return false;
        }
        if (r === 1) {
            return true;
        }
        if (r === p) {
            return false;
        }
        if (r === q) {
            return false;
        }
        if (r === 1 - p) {
            return false;
        }
        if (r === 1 - q) {
            return false;
        }
        if (r === 1 + p) {
            return false;
        }
        if (r === 1 + q) {
            return false;
        }
        s = 2 * s;
        t = 2 * t + 1;
        p = (p * p) % num;
        q = (q * q) % num;
        if (s === 0) {
            p = 1;
