function rearrange_bigger(n){
    // Convert the number to an array of its digits
    const digits = n.toString().split('');

    // Find the largest digit to the right of the current digit
    let maxIndex = -1;
    for (let i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            maxIndex = i;
            break;
        }
    }

    // If no such digit is found, the number is the largest possible rearrangement
    if (maxIndex === -1) {
        return -1;
    }

    // Find the smallest digit to the right of the current digit that is greater than the digit at maxIndex
    let minIndex = -1;
    for (let i = digits.length - 1; i > maxIndex; i--) {
        if (digits[i] > digits[maxIndex]) {
            minIndex = i;
            break;
        }
    }

    // Swap the digits at maxIndex and minIndex
    [digits[maxIndex], digits[minIndex]] = [digits[minIndex], digits[maxIndex]];

    // Sort the digits to the right of maxIndex in ascending order
    digits.splice(maxIndex + 1).sort();

    // Convert the array of digits back to a number
    return parseInt(digits.join(''), 10);
}

function rearrange_bigger(n) {
  // Convert the number to an array of digits
  let digits = n.toString().split('');

  // Sort the digits in descending order to get the largest possible number
  digits.sort((a, b) => b - a);

  // Find the first digit from the right that is smaller than the digit immediately to its right
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is already the largest possible
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit to the right of the found digit that is greater than it
  let j = digits.length - 1;
  while (digits[j] <= digits[i]) {
    j--;
  }

  // Swap the digits at positions i and j
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the remaining digits to get the smallest possible number
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''));
}

