    dp[index] = a[index];
    let max_sum = dp[index];

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
            max_sum = Math.max(max_sum, dp[i]);
        }
    }

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index] && i > k) {
            dp[i] = Math.max(dp[i], dp[k] + a[i]);
            max_sum = Math.max(max_sum, dp[i]);
        }
    }

    return max_sum;
}

