function max_product(arr) {
  // Initialize the maximum product to the smallest number possible
  let max_product = Number.NEGATIVE_INFINITY;
  // Initialize the current product to 1 (since multiplying by 1 doesn't change the product)
  let current_product = 1;

  // Iterate through the array
  for (let i = 0; i < arr.length; i++) {
    // Update the current product by multiplying it with the current element
    current_product *= arr[i];

    // Update the maximum product if the current product is greater
    max_product = Math.max(max_product, current_product);

    // If the current product becomes negative, reset it to 1 for a new subsequence
    if (current_product < 0) {
      current_product = 1;
    }
  }

  return max_product;
}

