function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    let minPath = [];
    let visited = new Set();

    function dfs(i, j, path, steps) {
        if (steps === k) {
            minPath = path.slice(); // Make a copy of the path
            return;
        }
        if (i < 0 || i >= N || j < 0 || j >= N || visited.has(`${i},${j}`)) return;

        visited.add(`${i},${j}`);
        path.push(grid[i][j]);

        for (const [dx, dy] of directions) {
            dfs(i + dx, j + dy, path, steps + 1);
        }

        path.pop();
        visited.delete(`${i},${j}`);
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

