    function backtrack(start, currentSum, path) {
        if (currentSum === test_list.length) {
            result.push(path.slice());
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            path.push(test_list[i]);
            backtrack(i + 1, currentSum + test_list[i], path);
            path.pop();
        }
    }
    backtrack(0, 0, []);
    return result;
}

function find_combinations(test_list) {
  const result = [];
  const combine = (arr, index, currentSum, currentCombination) => {
    if (currentSum === 0) {
      result.push([...currentCombination]);
      return;
    }
    for (let i = index; i < arr.length; i++) {
      if (arr[i] <= currentSum) {
        currentCombination.push(arr[i]);
        combine(arr, i + 1, currentSum - arr[i], currentCombination);
        currentCombination.pop();
      }
    }
  };

  combine(test_list, 0, 0, []);
  return result;
}

