  const sortedDigits = digits.slice().sort((a, b) => b - a);

  for (let i = digits.length - 1; i >= 0; i--) {
    if (digits[i] < sortedDigits[i]) {
      const smallerIndex = sortedDigits.indexOf(digits[i]);
      const temp = digits[i];
      digits[i] = sortedDigits[smallerIndex];
      sortedDigits[smallerIndex] = temp;

      const remainingDigits = digits.slice(0, i).concat(sortedDigits.slice(i + 1));
      const nextBiggerNumber = parseInt(remainingDigits.join(''));

      return nextBiggerNumber;
    }
  }

  return -1; // Return -1 if no bigger number can be formed.
}

