function max_product(arr) {
  // Initialize variables to keep track of the maximum product found and the current product
  let max_product = arr[0];
  let current_product = arr[0];

  // Iterate through the array starting from the second element
  for (let i = 1; i < arr.length; i++) {
    // If the current element is greater than the current product, update the current product
    if (arr[i] > current_product) {
      current_product = arr[i];
    } else {
      // Otherwise, update the current product to the current element times the current product
      current_product = arr[i] * current_product;
    }

    // Update the maximum product if the current product is greater than the maximum product
    if (current_product > max_product) {
      max_product = current_product;
    }
  }

  return max_product;
}

function max_product(arr) {
  // Initialize the maximum product with the first element
  let max_product = arr[0];
  // Initialize the minimum product with the first element (since multiplying by a negative number can make the product positive)
  let min_product = arr[0];
  // Initialize the result variable to store the maximum product found
  let result = arr[0];

  // Iterate through the array starting from the second element
  for (let i = 1; i < arr.length; i++) {
    // Check if the current element is positive
    if (arr[i] > 0) {
      // Update the maximum product if the current element is greater than the current maximum product
      max_product = Math.max(arr[i], max_product * arr[i]);
      // Update the minimum product if the current element is greater than the current minimum product
      min_product = Math.min(arr[i], min_product * arr[i]);
    } else {
      // Swap the maximum and minimum product if the current element is negative
      let temp = max_product;
      max_product = min_product;
      min_product = temp;
      // Update the maximum product if the current element is greater than the current maximum product
      max_product = Math.max(arr[i], max_product * arr[i]);
      // Update the minimum product if the current element is greater than the current minimum product
      min_product = Math.min(arr[i], min_product * arr[i]);
    }
    // Update the result with the maximum product found so far
    result = Math.max(result, max_product);
  }

  // Return the maximum product
  return result;
}

