function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(rows).fill(0).map(() => new Array(cols).fill(false));
  const path = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      path.push(grid[x][y]);
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, steps + 1);
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      path.push(grid[i][j]);
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
      path.pop();
    }
  }

  path.sort((a, b) => a - b);
  return path;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const minPathLength = Infinity;
    const minPathValues = [];

    const dfs = (row, col, pathLength, path) => {
        if (pathLength === k) {
            if (path.length < minPathLength) {
                minPathLength = path.length;
                minPathValues = path;
            }
            return;
        }

        visited[row][col] = true;
        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                dfs(newRow, newCol, pathLength + 1, path.concat(grid[newRow][newCol]));
            }
        }
        visited[row][col] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPathValues;
}

