function find_combinations(test_list){
    let result = [];
    let n = test_list.length;
    let sum = test_list.reduce((a, b) => a + b, 0);

    function helper(i, currentSum, currentCombination){
        if(currentSum === sum){
            result.push(currentCombination.slice());
            return;
        }
        if(i >= n || currentSum > sum){
            return;
        }

        currentCombination.push(test_list[i]);
        helper(i + 1, currentSum + test_list[i], currentCombination);
        currentCombination.pop();
        helper(i + 1, currentSum, currentCombination);
    }

    helper(0, 0, []);
    return result;
}

