function minPath(grid, k) {
    const N = grid.length;
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let minPath = [];

    function dfs(row, col, path, steps) {
        if (steps === k) {
            minPath = path;
            return;
        }

        visited[row][col] = true;

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                dfs(newRow, newCol, [...path, grid[newRow][newCol]], steps + 1);
            }
        }

        visited[row][col] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [
        [0, 1], [1, 0], [-1, 0], [0, -1]
    ];
    let minPathValue = Infinity;
    let minPathCells = [];

    const dfs = (i, j, path, pathLength) => {
        if (pathLength === k) {
            const currentPathValue = [...path].sort((a, b) => a - b).join('');
            if (currentPathValue < minPathValue) {
                minPathValue = currentPathValue;
                minPathCells = [...path];
            }
            return;
        }

        for (let dir of directions) {
            const newRow = i + dir[0];
            const newCol = j + dir[1];
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                dfs(newRow, newCol, [...path, grid[newRow][newCol]], pathLength + 1);
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPathCells;
}

