function Find_Min(lst){
  let minLen = Infinity;
  let minSubarray = [];

  for (let i = 0; i < lst.length; i++) {
    let currentLen = 0;
    let currentSubarray = [];

    for (let j = i; j < lst.length; j++) {
      currentSubarray.push(lst[j]);
      currentLen++;

      if (currentLen < minLen) {
        minLen = currentLen;
        minSubarray = currentSubarray;
      }
    }
  }

  return minSubarray;
}

function Find_Min(lst){
    let minLength = Infinity;
    let startIndex = 0;

    for (let i = 0; i < lst.length; i++) {
        let sum = 0;
        for (let j = i; j < lst.length; j++) {
            sum += lst[j];
            if (sum >= 0 && sum < minLength) {
                minLength = sum;
                startIndex = i;
            }
        }
    }

    return lst.slice(startIndex, startIndex + minLength);
}

function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index including the kth element
    const dp = Array.from({ length: n }, () => Array(k + 1).fill(0));

    // Base case: The maximum sum of increasing subsequence up to the first element is the element itself
    for (let i = 0; i < n; i++) {
        dp[i][0] = a[i];
    }

    // Fill the dp array
    for (let i = 1; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            dp[i][j] = dp[i - 1][j];
            if (a[i] > a[i - 1]) {
                dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - 1] + a[i]);
            }
        }
    }

    // The maximum sum of increasing subsequence up to the last index including the kth element
    return dp[n - 1][k];
}

function max_sum_increasing_subseq(a, n, index, k) {
  let dp = new Array(n + 1).fill(0);
  let maxSum = 0;

  for (let i = 0; i <= index; i++) {
    dp[i] = a[i];
    for (let j = i + 1; j <= n; j++) {
      if (a[j] > a[i] && j > k) {
        dp[j] = Math.max(dp[j], dp[i] + a[j]);
      }
    }
    maxSum = Math.max(maxSum, dp[j]);
  }

  return maxSum;
}

function find_combinations(test_list){
    let result = [];
    function backtrack(start, currentSum, currentCombination) {
        if (currentSum === 0) {
            result.push([...currentCombination]);
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            currentCombination.push(test_list[i]);
            backtrack(i + 1, currentSum - test_list[i], currentCombination);
            currentCombination.pop();
        }
    }
    backtrack(0, 0, []);
    return result;
}

function find_combinations(test_list){
    function combinationUtil(arr, index, sum, result) {
        if (sum === 0) {
            result.push([...result]);
            return;
        }
        if (index === arr.length) {
            return;
        }
        combinationUtil(arr, index + 1, sum, result);
        combinationUtil(arr, index + 1, sum - arr[index], result);
    }

    let result = [];
    combinationUtil(test_list, 0, 0, result);
    return result;
}

