function bell_Number(n){
  let bell = [1];
  for(let i = 1; i <= n; i++){
    let nextBell = 0;
    for(let j = 0; j < i; j++){
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

function bell_Number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = bell[bell.length - 1];
    for (let j = 1; j <= i; j++) {
      nextBell += bell[j - 1] * bell[i - j];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

