function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Set();
  const path = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      path.push(...grid[x][y]);
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
        visited.add(`${nx},${ny}`);
        dfs(nx, ny, steps + 1);
        visited.delete(`${nx},${ny}`);
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited.clear();
      path.length = 0;
      dfs(i, j, 0);
      if (path.length === k) {
        return path;
      }
    }
  }

  throw new Error('No path of length k found');
}

function minPath(grid, k) {
    const N = grid.length;
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (row, col, pathLength, path) => {
        if (pathLength === k) {
            if (pathLength < minPathLength || (pathLength === minPathLength && path.join('') < minPath.join(''))) {
                minPathLength = pathLength;
                minPath = path;
            }
            return;
        }

        visited[row][col] = true;
        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                dfs(newRow, newCol, pathLength + 1, path.concat(grid[newRow][newCol]));
            }
        }
        visited[row][col] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPath;
}

