function max_product(arr){
    // Sort the array in descending order
    arr.sort((a, b) => b - a);

    // Initialize variables to store the maximum product and the current product
    let max_product = 1;
    let current_product = 1;

    // Iterate through the sorted array
    for(let i = 0; i < arr.length; i++){
        // Multiply the current product by the current element
        current_product *= arr[i];

        // If the current product exceeds the maximum product, update the maximum product
        if(current_product > max_product){
            max_product = current_product;
        }

        // If the current product becomes negative, reset it to 1 (since multiplying by a negative number reverses the sign)
        if(current_product < 0){
            current_product = 1;
        }
    }

    // Return the maximum product
    return max_product;
}

