function k_smallest_pairs(nums1, nums2, k) {
    // Initialize a min-heap to store pairs
    const minHeap = new MinHeap();

    // Insert the first element of nums1 with its corresponding index in nums2 into the heap
    for (let i = 0; i < nums1.length; i++) {
        minHeap.push([nums1[i], nums2[i], i]);
    }

    // Initialize an array to store the result
    const result = [];

    // Extract the k smallest pairs from the heap
    for (let i = 0; i < k; i++) {
        const [num1, num2, index] = minHeap.pop();
        result.push([num1, num2]);

        // If there are more elements in nums2, insert the next pair
        if (index + 1 < nums2.length) {
            minHeap.push([num1, nums2[index + 1], index + 1]);
        }
    }

    return result;
}

