function find_combinations(test_list){
  const result = [];
  function backtrack(start, currentSum, currentCombination) {
    if (currentSum === 0) {
      result.push([...currentCombination]);
      return;
    }
    for (let i = start; i < test_list.length; i++) {
      if (test_list[i] <= currentSum) {
        currentCombination.push(test_list[i]);
        backtrack(i + 1, currentSum - test_list[i], currentCombination);
        currentCombination.pop();
      }
    }
  }
  backtrack(0, 0, []);
  return result;
}

function find_combinations(test_list) {
    const result = [];
    const n = test_list.length;
    const sum = test_list.reduce((acc, curr) => acc + curr, 0);
    const target = sum / 2;

    function backtrack(start, current, target) {
        if (current === target) {
            result.push([...current]);
            return;
        }
        if (current > target) {
            return;
        }
        for (let i = start; i < n; i++) {
            current.push(test_list[i]);
            backtrack(i + 1, current, target);
            current.pop();
        }
    }

    backtrack(0, [], target);
    return result;
}

