    let j = 0;
    while (j < i) {
      if (arr[j] < arr[i]) {
        // If the current element is greater than the previous element, update the maximum product
        max_product = Math.max(max_product, arr[j] * arr[i]);
        // Update the length of the longest increasing subsequence
        longest_subseq_length = Math.max(longest_subseq_length, longest_subseq_length + 1);
