function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const paths = [];

    function dfs(row, col, path, steps) {
        if (steps === k) {
            paths.push(path.slice());
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                dfs(newRow, newCol, [...path, grid[newRow][newCol]], steps + 1);
                visited.delete(`${newRow},${newCol}`);
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited.add(`${i},${j}`);
            dfs(i, j, [grid[i][j]], 1);
            visited.delete(`${i},${j}`);
        }
    }

    paths.sort((a, b) => {
        for (let i = 0; i < a.length && i < b.length; i++) {
            if (a[i] < b[i]) return -1;
            if (a[i] > b[i]) return 1;
        }
        return 0;
    });

    return paths[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const paths = [];

    const dfs = (row, col, path) => {
        if (path.length === k) {
            paths.push(path);
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, path.concat([grid[newRow][newCol]]));
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    paths.sort((a, b) => {
        for (let i = 0; i < a.length && i < b.length; i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return a.length - b.length;
    });

    return paths[0];
}

