function find_combinations(test_list){
  const combinations = [];
  const backtrack = (start, currentSum, currentCombination) => {
    if (currentSum === 0) {
      combinations.push(currentCombination.slice());
      return;
    }
    for (let i = start; i < test_list.length; i++) {
      if (currentSum + test_list[i] <= 0) break;
      currentCombination.push(test_list[i]);
      backtrack(i + 1, currentSum + test_list[i], currentCombination);
      currentCombination.pop();
    }
  };
  backtrack(0, 0, []);
  return combinations;
}

function find_combinations(test_list){
    const result = [];
    const combinations = (arr, target, index, current) => {
        if (target === 0) {
            result.push(current.slice());
            return;
        }
        for (let i = index; i < arr.length; i++) {
            if (arr[i] <= target) {
                current.push(arr[i]);
                combinations(arr, target - arr[i], i, current);
                current.pop();
            }
        }
    };
    combinations(test_list, 0, 0, []);
    return result;
}

