function k_smallest_pairs(nums1, nums2, k) {
    let pairs = [];
    const minHeap = new MinHeap();

    for (let i = 0; i < nums1.length && i < k; i++) {
        minHeap.push([nums1[i], nums2[0], 0]);
    }

    while (minHeap.size() && pairs.length < k) {
        const [num1, num2, index] = minHeap.pop();
        pairs.push([num1, num2]);

        if (index + 1 < nums2.length) {
