// Helper class to implement min heap
class MinHeap {
    constructor() {
        this.heap = [];
    }

    size() {
        return this.heap.length;
    }

    push(item) {
        this.heap.push(item);
        this.bubbleUp(this.size() - 1);
    }

    pop() {
        if (this.size() === 0) {
            return null;
        }

        const root = this.heap[0];
        this.heap[0] = this.heap[this.size() - 1];
        this.heap.pop();
        this.bubbleDown(0);

        return root;
    }

    bubbleUp(index) {
        while (index > 0 && this.heap[index] < this.heap[Math.floor((index - 1) / 2)]) {
            [this.heap[index], this.heap[Math.floor((index - 1) / 2)]] = [this.heap[Math.floor((index - 1) / 2)], this.heap[index]];
            index = Math.floor((index - 1) / 2);
        }
    }

    bubbleDown(index) {
        const left = 2 * index + 1;
        const right = 2 * index + 2;
        let smallest = index;

        if (left < this.size() && this.heap[left] < this.heap[smallest]) {
            smallest = left;
        }

        if (right < this.size() && this.heap[right] < this.heap[smallest]) {
            smallest = right;
        }

        if (smallest !== index) {
            [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
            this.bubbleDown(smallest);
        }
    }
}

function k_smallest_pairs(nums1, nums2, k) {
    const result = [];
    const minHeap = new MinHeap();

    for (let i = 0; i < nums1.length; i++) {
        for (let j = 0; j < nums2.length; j++) {
            if (minHeap.size() < k) {
                minHeap.push([nums1[i], nums2[j]]);
            } else {
                const top = minHeap.peek();
                if (top[0] + top[1] > nums1[i] + nums2[j]) {
                    minHeap.pop();
                    minHeap.push([nums1[i], nums2[j]]);
                }
            }
        }
    }

    while (!minHeap.isEmpty()) {
        result.push(minHeap.pop());
    }

    return result;
}

