  // Find the minimum length of any array in the input
  const minLength = Math.min(...Input.map(arr => arr.length));

  // Extract the first element from each array up to the minimum length
  const commonElements = Input.map(arr => arr.slice(0, minLength));

  // Check if all extracted elements are the same
  const firstElement = commonElements[0];
  const isCommon = commonElements.every(arr => arr.every((value, index) => value === firstElement[index]));

  // Return the common element if they are all the same, otherwise return null
  return isCommon ? firstElement : null;
}

