function minPath(grid, k) {
    const n = grid.length;
    const visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    function dfs(x, y, path, count) {
        if (path.length === count) {
            return [path];
        }
        const result = [];
        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                visited[nx][ny] = true;
                result.push(...dfs(nx, ny, [...path, grid[nx][ny]], count));
                visited[nx][ny] = false;
            }
        }
        return result;
    }

    let minPath = Infinity;
    let result = [];
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const paths = dfs(i, j, [grid[i][j]], k);
            for (const path of paths) {
                if (path.join('') < minPath) {
                    minPath = path.join('');
                    result = path;
                }
            }
        }
    }

    return result;
}

function minPath(grid, k) {
    const n = grid.length;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const visited = new Set();
    const queue = [{ row: 0, col: 0, path: [] }];
    let minPath = [];

    while (queue.length > 0) {
        const { row, col, path } = queue.shift();
        if (path.length === k) {
            if (minPath.length === 0 || path.sort().join(',') < minPath.sort().join(',')) {
                minPath = path;
            }
            continue;
        }
        if (visited.has(`${row},${col}`)) continue;
        visited.add(`${row},${col}`);

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n) {
                queue.push({ row: newRow, col: newCol, path: [...path, grid[newRow][newCol]] });
            }
        }
    }

    return minPath;
}

