function get_total_number_of_sequences(m, n){
  // Base case: If n is 1, there is only one sequence (the number itself).
  if (n === 1) {
    return m;
  }

  // Initialize the result to 0.
  let result = 0;

  // Iterate from 2 to m (inclusive).
  for (let i = 2; i <= m; i++) {
    // Add the number of sequences of length n-1 that can be formed with the current number i.
    result += get_total_number_of_sequences(m, n - 1);
  }

  // Return the total number of sequences.
  return result;
}

