class MinHeap {
  constructor() {
    this.heap = [];
  }

  size() {
    return this.heap.length;
  }

  push(item) {
    this.heap.push(item);
    this.bubbleUp(this.size() - 1);
  }

  pop() {
    if (this.size() === 0) {
      return null;
    }

    const root = this.heap[0];
    this.heap[0] = this.heap[this.size() - 1];
    this.heap.pop();
    this.bubbleDown(0);

    return root;
  }

  bubbleUp(index) {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (this.heap[parentIndex][0] > this.heap[index][0]) {
        [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];
        index = parentIndex;
      } else {
        break;
      }
    }
  }

  bubbleDown(index) {
    const leftChildIndex = 2 * index + 1;
    const rightChildIndex = 2 * index + 2;
    let largestIndex = index;

    if (leftChildIndex < this.size() && this.heap[leftChildIndex][0] < this.heap[largestIndex][0]) {
      largestIndex = leftChildIndex;
    }

    if (rightChildIndex < this.size() && this.heap[rightChildIndex][0] < this.heap[largestIndex][0]) {
      largestIndex = rightChildIndex;
    }

    if (largestIndex !== index) {
      [this.heap[largestIndex], this.heap[index]] = [this.heap[index], this.heap[largestIndex]];
      this.bubbleDown(largestIndex);
    }
  }
}

