function minPath(grid, k) {
  const n = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
  const path = [];
  const minPathLength = Infinity;
  const pathValues = [];

  function dfs(x, y, steps) {
    if (steps === k) {
      if (steps === minPathLength) {
        pathValues.push([...path]);
      } else if (steps < minPathLength) {
        minPathLength = steps;
        pathValues = [([...path])];
      }
      return;
    }

    visited[x][y] = true;
    path.push(grid[x][y]);

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
        dfs(nx, ny, steps + 1);
      }
    }

    path.pop();
    visited[x][y] = false;
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      dfs(i, j, 0);
    }
  }

  return pathValues[0];
}

function tri(n) {
