function rearrange_bigger(n) {
  let str = n.toString();
  let len = str.length;
  let maxIndex = -1;

  // Find the largest digit to the right of the last digit
  for (let i = len - 2; i >= 0; i--) {
    if (str[i] < str[i + 1]) {
      maxIndex = i;
      break;
    }
  }

  // If no such digit is found, return -1
  if (maxIndex === -1) {
    return -1;
  }

  // Find the smallest digit to the right of the maxIndex
  let minIndex = maxIndex + 1;
  for (let i = len - 1; i > maxIndex; i--) {
    if (str[i] > str[minIndex]) {
      minIndex = i;
    }
  }

  // Swap the digits at maxIndex and minIndex
  [str[maxIndex], str[minIndex]] = [str[minIndex], str[maxIndex]];

  // Sort the digits to the right of maxIndex in ascending order
  let rightPart = str.slice(maxIndex + 1).split('').sort().join('');

  // Combine the digits to form the next bigger number
  return parseInt(str.slice(0, maxIndex + 1) + rightPart);
}

function rearrange_bigger(n) {
    // Convert the number to an array of digits
    const digits = Array.from(String(n), Number);

    // Find the index of the first digit from the right that is smaller than the digit immediately to its right
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest possible permutation, and there is no next bigger number
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of the swapped digit in ascending order
    digits.splice(i + 1).sort((a, b) => a - b);

    // Convert the array of digits back to a number and return it
    return parseInt(digits.join(''), 10);
}

