function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize the DP array to store the maximum sum of increasing subsequence up to each index
    const dp = new Array(n).fill(0);

    // Base case: The maximum sum of increasing subsequence up to the first element is the element itself
    dp[0] = a[index];

    // Fill the DP array
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            // Check if the current element is greater than the previous element and can be included in the increasing subsequence
            if (a[i] > a[j] && dp[i] < dp[j] + a[i]) {
                dp[i] = dp[j] + a[i];
            }
        }
        // Check if the kth element is greater than the current element and can be included in the increasing subsequence
        if (k > i && a[k] > a[i] && dp[k] < dp[i] + a[k]) {
            dp[k] = dp[i] + a[k];
        }
    }

    // The maximum sum of increasing subsequence up to the last index is the maximum value in the DP array
    return Math.max(...dp);
}

