    let max_sum = 0;

    // Iterate through each element in the array
    for (let i = 0; i < n; i++) {
        // If the current element is greater than the previous element, update the dp array
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
        }
