function minPath(grid, k) {
  const N = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const minPathLength = Infinity;
  const minPath = [];

  function dfs(row, col, path, steps) {
    if (steps === k && !visited[row][col]) {
      if (path.length < minPathLength) {
        minPath = [...path];
        minPathLength = path.length;
      }
      return;
    }

    if (steps >= k || row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
      return;
    }

    visited[row][col] = true;
    path.push(grid[row][col]);

    for (const [dr, dc] of directions) {
      dfs(row + dr, col + dc, path, steps + 1);
    }

    visited[row][col] = false;
    path.pop();
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, [], 0);
    }
  }

  return minPath;
}

function minPath(grid, k){
    const n = grid.length;
    let minPath = [];
    let minDist = Infinity;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left

    function dfs(row, col, steps, path){
        if(steps === k){
            if(path.length < minDist || (path.length === minDist && path.join(',') < minPath.join(','))){
                minPath = [...path];
                minDist = path.length;
            }
            return;
        }

        for(let dir of directions){
            let newRow = row + dir[0];
            let newCol = col + dir[1];
            if(newRow >= 0 && newRow < n && newCol >= 0 && newCol < n){
                dfs(newRow, newCol, steps + 1, [...path, grid[newRow][newCol]]);
            }
        }
    }

    for(let i = 0; i < n; i++){
        for(let j = 0; j < n; j++){
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    return minPath;
}

