function minPath(grid, k) {
    const N = grid.length;
    const directions = [
        [0, 1],
        [1, 0],
        [-1, 0],
        [0, -1]
    ];

    function dfs(row, col, path, steps) {
        if (steps === k) {
            return [path];
        }

        const result = [];
        for (const [dx, dy] of directions) {
            const newRow = row + dy;
            const newCol = col + dx;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                const nextPath = [...path, grid[newRow][newCol]];
                const nextSteps = steps + 1;
                const nextResults = dfs(newRow, newCol, nextPath, nextSteps);
                result.push(...nextResults);
            }
        }

        return result;
    }

    const allPaths = [];
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            const path = [grid[i][j]];
            const steps = 1;
            const results = dfs(i, j, path, steps);
            allPaths.push(...results);
        }
    }

    // Sort the paths lexicographically
    allPaths.sort((a, b) => {
        for (let i = 0; i < a.length && i < b.length; i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return a.length - b.length;
    });

    // Return the first path
    return allPaths[0];
}

function minPath(grid, k){
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathLength = Infinity;
  const minPathValues = [];

  const dfs = (x, y, steps, path, minPathLength, minPathValues) => {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        path.push(grid[nx][ny]);
        dfs(nx, ny, steps + 1, path, minPathLength, minPathValues);
        path.pop();
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 1, [grid[i][j]], minPathLength, minPathValues);
    }
  }

  return minPathValues;
}

