    let minPath = [];

    const dfs = (i, j, length) => {
        if (length === k) {
            if (path.length < minPathLength) {
                minPath = [...path];
                minPathLength = path.length;
            }
            return;
        }

        if (i < 0 || i >= N || j < 0 || j >= N || visited[i][j] || grid[i][j] === 0) {
            return;
        }

        visited[i][j] = true;
        path.push(grid[i][j]);

        for (const [dx, dy] of directions) {
            dfs(i + dx, j + dy, length + 1);
        }

        path.pop();
        visited[i][j] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (grid[i][j] !== 0) {
                dfs(i, j, 1);
            }
        }
    }

    return minPath;
}

