function rearrange_bigger(n) {
  // Convert the number to an array of digits
  const digits = Array.from(String(n), Number);

  // Find the first digit from the right that is smaller than the digit immediately to its right
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is the largest possible permutation
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit to the right of i that is greater than digits[i]
  let j = digits.length - 1;
  while (j >= 0 && digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of i
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''));
}

function rearrange_bigger(n){
    // Convert number to string to manipulate its digits
    let str = n.toString();
    let len = str.length;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = len - 2;
    while (i >= 0 && str[i] >= str[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is already the largest permutation
    if (i === -1) {
        return -1;
    }

    // Find the smallest digit to the right of i that is larger than str[i]
    let j = len - 1;
    while (j >= 0 && str[j] <= str[i]) {
        j--;
    }

    // Swap the digits at positions i and j
    let temp = str[i];
    str[i] = str[j];
    str[j] = temp;

    // Sort the digits to the right of i in ascending order
    let left = str.slice(0, i + 1);
    let right = str.slice(i + 1).split('').sort().join('');
    str = left + right;

    // Convert the result back to number
    return parseInt(str, 10);
}

