function find_combinations(test_list){
  if (!test_list || !test_list.length) return [];

  const results = [];

  function backtrack(start, currentSum, path) {
    if (currentSum === 0) {
      results.push(path.slice());
      return;
    }

    for (let i = start; i < test_list.length; i++) {
      const num = test_list[i];
      path.push(num);
      backtrack(i + 1, currentSum - num, path);
      path.pop();
    }
  }

  backtrack(0, 0, []);
  return results;
}

function find_combinations(test_list){
    let combinations = [];
    let sum = 0;
    let visited = new Set();

    function backtrack(start, current_sum, current_combination) {
        if (current_sum === sum) {
            combinations.push(current_combination.slice());
            return;
        }
        if (current_sum > sum) {
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            if (!visited.has(i)) {
                visited.add(i);
                current_combination.push(test_list[i]);
                backtrack(i + 1, current_sum + test_list[i], current_combination);
                current_combination.pop();
                visited.delete(i);
            }
        }
    }

    backtrack(0, 0, []);
    return combinations;
}

