function rearrange_bigger(n) {
    let digits = n.toString().split('');
    let sortedDigits = digits.sort((a, b) => b - a);
    let index = 0;

    // Find the first digit that is smaller than the digit immediately after it
    for (let i = 0; i < digits.length - 1; i++) {
        if (digits[i] < digits[i + 1]) {
            index = i;
            break;
        }
    }

    if (index === -1) {
        return -1; // No bigger number can be formed
    }

    // Find the smallest digit to the right of index that is greater than digits[index]
    let smallestIndex = index + 1;
    for (let i = index + 1; i < digits.length; i++) {
        if (digits[i] > digits[index] && digits[i] < digits[smallestIndex]) {
            smallestIndex = i;
        }
    }

    // Swap digits[index] and digits[smallestIndex]
    [digits[index], digits[smallestIndex]] = [digits[smallestIndex], digits[index]];

    // Sort the digits to the right of index in ascending order
    digits.splice(index + 1);
    digits.sort((a, b) => a - b);

    // Convert the array of digits back to a number
    return parseInt(digits.join(''));
}

function rearrange_bigger(n){
  // Convert the number to an array of its digits
  let digits = n.toString().split('');

  // Start from the second last digit and check if it's smaller than the digit immediately before it
  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      // Find the smallest digit to the right of the current digit that is greater than it
      let j = i + 1;
      while (j < digits.length && digits[j] <= digits[i]) {
        j++;
      }

      // Swap the found digits
      [digits[i], digits[j - 1]] = [digits[j - 1], digits[i]];

      // Sort the digits to the right of the swapped digit in ascending order
      digits.splice(i + 1, digits.length - (i + 1), ...digits.slice(i + 1).sort());

      // Convert the array of digits back to a number
      return parseInt(digits.join(''));
    }
  }

  // If no bigger number can be formed, return -1
  return -1;
}

